}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":14},"_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.7,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":1.4,"sizes":[]},"size":"small"},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"739044b0","elType":"section","settings":{"layout":"full_width","background_background":"classic","background_color":"#59DA7A94"},"elements":[{"id":"15d01ebf","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic"},"elements":[{"id":"1e360d7c","elType":"widget","settings":{"title":"מאמן כושר אישי מומלץ לילדים","align":"center","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":33,"sizes":[]},"typography_font_weight":"600","typography_letter_spacing":{"unit":"px","size":0.3,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":25,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"a362784","elType":"widget","settings":{"title":"תומר אלמוג מאמן כושר ילדים מומלץ- אימון כושר אישי לילדים ונוער","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"92d0a0e","elType":"widget","settings":{"editor":"<p>פרופיל מאמן <a href="https://www.limudnaim.co.il/%D7%9E%D7%90%D7%9E%D7%9F-%D7%90%D7%99%D7%A9%D7%99/%D7%AA%D7%95%D7%9E%D7%A8-%D7%90%D7%9C%D7%9E%D7%95%D7%92">לימוד נעים</a> - 10 אימונים ותראו את השינוי .<a style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); background-color: rgba(89, 218, 122, 0.58);" href="https://www.sport4you.co.il/%d7%9e%d7%90%d7%9e%d7%9f-%d7%9b%d7%95%d7%a9%d7%a8-%d7%90%d7%99%d7%a9%d7%99-%d7%9c%d7%99%d7%9c%d7%93%d7%99%d7%9d-%d7%a8%d7%9e%d7%aa-%d7%94%d7%a9%d7%a8%d7%95%d7%9f/">אימוני כושר לילדים ברמת השרון</a><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">, הרצליה, תל אביב, </span><a style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); background-color: rgba(89, 218, 122, 0.58);" href="https://www.sport4you.co.il/%d7%90%d7%99%d7%9e%d7%95%d7%9f-%d7%99%d7%9c%d7%93%d7%99%d7%9d-%d7%95%d7%a0%d7%95%d7%a2%d7%a8/%d7%90%d7%99%d7%9e%d7%95%d7%9f-%d7%90%d7%99%d7%a9%d7%99-%d7%94%d7%95%d7%a8%d7%94-%d7%95%d7%99%d7%9c%d7%93/">אימון הורה וילד</a><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">, אימונים יחודיים לבעלי הפרעת קשב וריכוז</span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"1919669","elType":"widget","settings":{"title":"מהם היתרונות והצורך באימון כושר אישי לילדים?","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"ea43f3f","elType":"widget","settings":{"editor":"<p>מאמן כושר אישי לילדים ונוער – חיפוש אחר מאמן כושר מומלץ זה מהדברים החשובים ביותר שהורה יכול להעניק עבור לילדיו, בעיקר, בעידן המסכים והיצמדות של ילדים ובני נוער לטלוויזיה ולטלפונים הניידים, ובתקופת הקורונה נמצא בעלייה מתמדת, והיצמדות לשיעורים ומפגשים שנערכים ב ZOOM . אלו בין שלל הגורמים ל<span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">מגיפת ההשמנה בעולם בכלל ואצל ילדי ישראל בפרט וזו נמצאת בעלייה מתמדת אשר ממקמת את ילדי ישראל ב<a href="https://www.ynet.co.il/articles/0,7340,L-4860128,00.html">מקום השני בעולם</a> - על שלל המחלות שמגיעות עמה כגון סוכרת, לחץ דם ועוד..כל שעת כושר שתעניקו להם שווה זהב. </span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">כל אלו גורמים ל-בעיות רבות בקרב הילדים:</span></p><p>1. התכנסות ושהייה רבה מאוד בתוך הבית הגורמת לשעמום, אכילה בלתי מבוקרת ושל מזונות שאינם בריאים<span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );"> ומלאים סוכר ושומן</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">2. הצמדות למסכים ובכך הימנעות מלעסוק בפעילות גופנית כלשהי החשובה לשמירה על משקל תקין</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">3. ירידה בביטחון העצמי והדימוי הגופני </span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">פעילות גופנית מסייעת לילדים ונוער </span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">בהווה וגם עוזרת להם בעתיד לכשיהיו מבוגרים, מכיוון ופעילות גופנית שרירית מסייעת להם להימנע מבעיות של איבוד צפיפות עצם ומסת שריר כשיהיו מבוגרים</span></p><p>מחקרים רבים קבעו שישנה חשיבות קריטית ב<a href="https://www.one.co.il/Article/294661.html">אימוני התנגדות של ילדים</a> ונוער לחיזוק שרירי הגוף ועצמות הגוף, ומסייעת בהעלאת ביטחונם העצמי, שמירה על משקל תקין ולא פחות חשוב יצירת מאזן שרירי שיישמר לעתיד בהיותם מבוגרים בריאים<br />מסגרות האימון לילדים ונוער מבוססת על ניסיוני הרב בבניית תוכנית אימון כושר הכוללת מרכיבים מגוונים המעניקה לילד המתאמן לשפר את כלל מרכיבי הכושר הגופני,<br />שיפור מדדים בריאותיים, פיזיים, מוטוריים,יכולות מוטוריקה גסה ועדינה, יכולת חשיבה, אסטרטגיה, קבלת החלטות, משמעת עצמית ואיפוק וכמובן הקניית הרגלי תזונה נכונה ומאוזנת כאורח חיים</p>"},"elements":[],"widgetType":"text-editor"},{"id":"0f70011","elType":"widget","settings":{"title":"אימון כושר אישי לילדים - למי הוא מיועד?","header_size":"h4","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"e5324af","elType":"widget","settings":{"editor":"<p>אימון כושר אישי לילדים על ידי מאמן כושר אישי מומלץ לילדים – עבור ילדים בגילאי כיתה א' ועד בני נוער המעוניינים בהורדת משקל, חיטוב ושיפור כושרם האישי ועד להכנה לצבא.</p><p>מסגרות האימון לילדים ונוער מבוססת על ניסיוני הרב בבניית תוכנית אימון כושר הכוללת מרכיבים מגוונים המעניקה לילדים המתאמנים יכולת לשפר את כלל מרכיבי הכושר הגופני,<br />שיפור מדדים בריאותיים, פיזיים, מוטוריקה גסה ועדינה, יכולת חשיבה, אסטרטגיה, קבלת החלטות, משמעת עצמית ואיפוק וכמובן הקניית הרגלי תזונה נכונה ומאוזנת כאורח חיים<br />הילדים יקבלו כלים לעבודה עצמית שתלווה אותם לעתיד וביכולת לעסוק בפעילות גופנית כדרך חיים<br />המטרה היא יצירת הרגלים טובים שח אורח חיים פעיל ולא יושבני, ומתן דגש על הזנה בריאה שמתדלקת את הגוף ולא מכבה אותו.<br />בעתיד יהוו אימונים שיעבור כילד בסיס חזק ואיתן ובסבירות גבוהה שיעסוק בפעילות גופנית וישמור על תזונה מאוזנת ובריאה ומשקל תקין לאורך כך חייו.<br />מעבר לכך שתקופה האימונים תתאפיין בהתפתחות מוטורית עדינה וגסה, העלאת רמת הביטחון העצמי והדימוי העצמי</p>"},"elements":[],"widgetType":"text-editor"},{"id":"df8042f","elType":"widget","settings":{"title":"אזורי האימון","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":20,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"31fdfdaf","elType":"widget","settings":{"editor":"<p>אימוני כושר לילדים ברמת השרון, הרצליה, תל אביב</p><p>הרצליה: פארק הרצליה, גליל ים, חופי הים</p><p>תל אביב: פארק הירקון, הדר יוסף,&nbsp;</p>
<p>רמת השרון: פארק הנצח רמת השרון, פארק אלכסנדרוני, פארק הנביאים, נווה רום, קאנטרי קלאב רמת השרון, שרונית, בבית ההורים<br>מאמן כושר אישי לילדים ונוער – זה מהדברים החשובים ביותר שהורה יכול להעניק עבור לילדיו.</p><p>צלצלו או השאירו הודעה ונתחיל בתהליך!</p>","text_color":"#030303","__globals__":{"typography_typography":"globals/typography?id=accent"}},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"79106b60","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},"margin_tablet":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"30","right":"30","bottom":"30","left":"30","isLinked":true},"padding_tablet":{"unit":"px","top":"40","right":"80","bottom":"40","left":"80","isLinked":false},"_timestamp_":"v1UUJmcjcvMjNHWjFyRUdDK1A3T29ZQT09","margin_mobile":{"unit":"px","top":"80","right":0,"bottom":"0","left":0,"isLinked":false},"_ha_condition_list":[{"_id":"cfd1c98"}],"__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"31c28347","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"border_border":"solid","background_background":"classic","background_color":"#A0CFB8","_ha_condition_list":[{"_id":"456ba75"}]},"elements":[{"id":"3e251be4","elType":"widget","settings":{"title":"להסבר על מסלולי האימון - השאירו פרטים","size":"large","align":"center","title_color":"#030303","typography_typography":"custom","typography_font_siz