לות האימון"}},{"@type":"Question","name":"למי מתאים אימון עם מאמן כושר אישי לילדים?","acceptedAnswer":{"@type":"Answer","text":"אימון כושר אישי יכול להתאים לכל רמות הכושר של הילדים, ולכל שכבות של הגילים לילדים. אימון אישי, קבוצתי קטן, הורה וילד, בעלי הפרעות קשב וריכוז, ילדים עם מוגבלות. כנסו לאתר וקבלו איפיון מלא לפי הצרכים שלכם כמתאמנים וצרו קשר לפרטים מלאים"}},{"@type":"Question","name":"אילו מיקומים מתאימים לאימון כושר אישי לילדים?","acceptedAnswer":{"@type":"Answer","text":"ניתן לקיים אימון אישי כושר לילדים כמעט בכל מקום וזמן שתחפצו - העיקר שיהיה נוח להם - בבית, ים, אצטדיון, פארק, במרפסת, בחדר כושר ובהרבה מקומות נוספים. כנסו לאתר לאפיון מקום האימון המתאים ביותר"}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"275f1db1","elType":"widget","settings":{"tabs":[{"tab_title":"כמה עולה מאמן כושר אישי לילדים?","tab_content":"<p>מאמן כושר אישי ילדים מומלץ שמתמחה בגילים אלו, ויודע להתאים את התרגילים והמשחקים שישפרו את יכולת הקורדינציה, היכולת השרירית והביטחון העצמי - לכך צריך מאמן בעל ניסיון. לכן המחירים נעים למאמנים שאינם עם ניסיון ועד מומחים בתחום והמחירים נעים בין 100 ש"ח ל 300 ש"ח לאימון גופני לילדים. כנסו לאתר לאפיון מלא של עלות האימון</p>","_id":"229e5f7"},{"tab_title":"למי מתאים אימון עם מאמן כושר אישי לילדים?","tab_content":"<p>אימון כושר אישי יכול להתאים לכל רמות הכושר של הילדים, ולכל שכבות של הגילים לילדים. אימון אישי, קבוצתי קטן, הורה וילד, בעלי הפרעות קשב וריכוז, ילדים עם מוגבלות. כנסו לאתר וקבלו איפיון מלא לפי הצרכים שלכם כמתאמנים וצרו קשר לפרטים מלאים</p>","_id":"3867294"},{"tab_title":"אילו מיקומים מתאימים לאימון כושר אישי לילדים?","tab_content":"<p>ניתן לקיים אימון אישי כושר לילדים כמעט בכל מקום וזמן שתחפצו - העיקר שיהיה נוח להם - בבית, ים, אצטדיון, פארק, במרפסת, בחדר כושר ובהרבה מקומות נוספים. כנסו לאתר לאפיון מקום האימון המתאים ביותר</p>","_id":"e3be0ad"}],"title_color":"#000","title_typography_typography":"custom","title_typography_font_family":"Montserrat","title_typography_font_size":{"unit":"px","size":28,"sizes":[]},"title_typography_font_size_mobile":{"unit":"px","size":25,"sizes":[]},"title_typography_font_weight":"600","content_color":"#000","__globals__":{"title_color":"globals/colors?id=68f6ec0b","content_color":"globals/colors?id=68f6ec0b","tab_active_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"toggle"}],"isInner":false}],"isInner":false},{"id":"1806b426","elType":"section","settings":{"gap":"narrow","custom_height":{"unit":"px","size":65,"sizes":[]},"layout":"full_width","background_background":"classic","__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"2ea2249e","elType":"column","settings":{"_column_size":100},"elements":[{"id":"37e3a4d2","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"},{"id":"16ecc18c","elType":"widget","settings":{"youtube_url":"https://www.youtube.com/watch?v=qnZj0NIhzd4","vimeo_url":"https://vimeo.com/235215203","dailymotion_url":"https://www.dailymotion.com/video/x6tqhqb","yt_privacy":"yes","aspect_ratio":"219","css_filters_css_filter":"custom","start":2,"autoplay":"yes","play_on_mobile":"yes","mute":"yes"},"elements":[],"widgetType":"video"},{"id":"301c85cf","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"}],"isInner":false}],"isInner":false},{"id":"13d5bbc4","elType":"section","settings":{"height":"min-height","custom_height":{"unit":"px","size":0,"sizes":[]}},"elements":[{"id":"5f840c48","elType":"column","settings":{"_column_size":100},"elements":[{"id":"166810ac","elType":"widget","settings":{"title":"מאמרים אחרונים","header_size":"h5","align":"center","typography_typography":"custom","typography_font_size":{"unit":"px","size":45,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":33,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_letter_spacing":{"unit":"px","size":6.8,"sizes":[]},"__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"10