}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":14},"_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.7,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":1.4,"sizes":[]},"size":"small"},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"6b0efc2","elType":"section","settings":{"layout":"full_width","background_background":"classic","background_color":"#59DA7A94"},"elements":[{"id":"6f1dea65","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic"},"elements":[{"id":"3e32a550","elType":"widget","settings":{"title":"קבוצת אתלטיקה וכושר גופני לילדים","align":"center","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":28,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":22,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"91b2f99","elType":"widget","settings":{"title":"תומר אלמוג מאמן כושר אישי מומלץ לקבוצות ילדים ונוער","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","header_size":"h3","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"f76528a","elType":"widget","settings":{"editor":"<p><b>קבוצות אתלטיקט ילדים - קבוצת <a href="https://www.sport4you.co.il/%d7%90%d7%99%d7%9e%d7%95%d7%9f-%d7%99%d7%9c%d7%93%d7%99%d7%9d-%d7%95%d7%a0%d7%95%d7%a2%d7%a8/">אתלטיקה וכושר לילדים ונוער</a> - </b><b style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size );">אימונים מהנים תוך שימוש באביזרים רבים, משחקים ותנועה רבה, פעילות מהנה ובונה!</b></p><p>אנו נמצאים בעידן בו הילדים מתכנסים יותר - נצמדים למסכים ואז הגיעה גם הקורונה לחיינו וגרמה להחמרה אצל כולנו ובעיקר אצל הילדים - הבהייה במסכי הטלוויזיה, הסמארטפונים,</p><p>בקונסולות הפלייסטיישן ואקסבוקס (PLAYSTATION, X-BOX) ו – ZOOM גרמו וגורמים נזקים גדולים ובעיות רבות לילדים:</p><p>א. התכנסות לשהיה בתוך הבית ואכילה בלתי מבוקרת של מזון בכלל ומזון לא בריא בפרט, כגון: מזונות שומניים, מעובדים, מלאי סוכר, חוסר גיוון בירקות ופירות</p><p>ב. הצמדות למסכים ובכך הימנעות מלעסוק בפעילות גופנית הקריטית לילדים תוך שהמלצות ארגון הבריאות העולמית עודת על כשעה וחצי פעילו ביום.</p><p>ג. הימנעות ממפגשים חברתיים פיזיים ולא דרך המחשבים או הפלאפונים</p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">מסגרות האימון לילדים ונוער ב- קבוצות אתלטיקט ילדים ונוער - מבוססת על ניסיוני הרב בבניית תוכנית אימון כושר הכוללת מרכיבים מגוונים המעניקה לילד המתאמן לשפר את כלל <a href="https://www.one.co.il/Article/294661.html">מרכיבי הכושר הגופני</a>,</span></p><p><a href="https://wingate.org.il/category/articles/%D7%90%D7%99%D7%9E%D7%95%D7%9F-%D7%9B%D7%95%D7%A9%D7%A8-%D7%92%D7%95%D7%A4%D7%A0%D7%99-%D7%95%D7%91%D7%A8%D7%99%D7%90%D7%95%D7%AA/">שיפור מדדים בריאותיים, פיזיים,</a> מוטוריים, גסה ועדינה, יכולת חשיבה, אסטרטגיה, קבלת החלטות, משמעת עצמית ואיפוק וכמובן הקניית הרגלי תזונה נכונה ומאוזנת כאורח חיים קבוע</p>"},"elements":[],"widgetType":"text-editor"},{"id":"04e8a6b","elType":"widget","settings":{"title":"אימון כושר אתלטיקה לילדים ונוער -למי הוא מיועד?","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","header_size":"h4","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":21,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"5019a8c","elType":"widget","settings":{"editor":"<p style="color: #030303;">אימון קבוצות אתלטיקט ילדים ונוער – עבור ילדים בגילאי היסודי ובני נוער המעוניינים בשיפור כלל מדדי הכושר והבריאות, הפחתת משקל, חיטוב ושיפור כושרם האישי ועד להכנה לצבא והכנה לתחרויות ריצה <span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ושיפור כושר ספציפי לענפי הכדור.</span></p><p style="color: #030303;">המטרה היא יצירת הרגלים טובים של אורח חיים פעיל ולא יושבני, ומתן דגש על הזנה בריאה שמתדלקת את הגוף ולא מכבה אותו ומעניקה לו חיות ואפשרות לגדול כבן אדם בוגר ובריא</p><p style="color: #030303;">הילדים המתאמנים כדרך קבע יהיה זה עבורם בסיס חזק ואיתן לעתיד ובסבירות גבוהה שיעסקו בפעילות גופנית וישמרו על תזונה מאוזנת ובריאה ומשקל תקין.</p><p style="color: #030303;">מעבר לכך שתקופה האימונים תתאפיין בהתפתחות מוטורית עדינה וגסה, העלאת רמת הביטחון העצמי והדימוי העצמי והאמונה של כל ילד וילדה העצמם</p>"},"elements":[],"widgetType":"text-editor"},{"id":"98b5afd","elType":"widget","settings":{"title":"קבוצות אתלטיקט רמת השרון","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","header_size":"h4","align_mobile":"center"},"elements":[],"widgetType":"heading"},{"id":"529db86","elType":"widget","settings":{"editor":"<p><b>לוז אימוני אגודת הספורט רמת השרון</b></p><div dir="auto"><b>***קבוצות אתלטיקט לילדים***באיצטדיון האתלטיקה, (רח' הזית 6) רמת השרון בימים שני ורביעי<img src="https://static.xx.fbcdn.net/images/emoji.php/v9/tc4/1.5/16/1f3c3_200d_2642.png" alt="🏃‍♂️" width="16" height="16" /> </b></div><div dir="auto"><div dir="auto"><b>כיתות א-ב 16:30עד 17:15</b></div><div dir="auto"><b>כיתות ג-ד 17:10 עד 18:15</b></div><div dir="auto"><b>כיתות ה-ו 18:00 עד 19:00</b></div><div dir="auto"><b> </b><b> </b></div><div dir="auto"><b>אימונים המחזקים את היכולות האתלטיות שכוללות את כל מרכיבי הכושר הגופני ומקצועות האתלטיקה -</b></div><div dir="auto"><b>ריצות וזריזות, קפיצות,זריקות, קורדינציה בדגש על העלאת הביטחון העצמי של הילדים, אהבת הספורט וערכי החברות ותחרותיות נכונה.</b></div><div dir="auto"><span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size );"><b>הכל באמצעות משחקים ואביזרים מגוונים מוזמנים לבוא לשיעור ניסיון 🙏 תומר 052-6982993</b></span></div></div>"},"elements":[],"widgetType":"text-editor"},{"id":"60884de6","elType":"widget","settings":{"editor":"<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size );"><b>א</b></span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ם קשה לך להתמיד באימונים – אני אסייע לך להפוך את האימון הגופני לדרך חיים!</span></p><p>אם אינך רואה תוצאות – אני אראה לך את הדרך לאימון יעיל ואפקטיבי!<br />אם אין לך זמן להתאמן – אני מגיע לביתך ומאמן אותך לתוצאות במינימום השקעת זמן!</p>","text_color":"#030303","__globals__":{"typography_typography":"globals/typography?id=accent"}},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"7fbf189a","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},