}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":14},"_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.7,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":1.4,"sizes":[]},"size":"small"},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"3695472d","elType":"section","settings":{"layout":"full_width","background_background":"classic","background_color":"#59DA7A94"},"elements":[{"id":"5e0d3197","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic"},"elements":[{"id":"1c066424","elType":"widget","settings":{"title":"מאמן כושר אישי הורים וילדים","align":"center","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":33,"sizes":[]},"typography_font_weight":"600","typography_letter_spacing":{"unit":"px","size":0.3,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":25,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"46c1eed","elType":"widget","settings":{"title":"תומר אלמוג מאמן כושר אישי מומלץ להורה וילד.ה","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"e09c865","elType":"widget","settings":{"editor":"<p><b>אימון אישי הורה וילד על ידי <a href="https://www.sport4you.co.il/about-me/">תומר אלמוג מאמן כושר אישי </a>הורה וילד מומלץ! - </b>מאמן כושר אישי להורה וילד.ה ברמת השרון, הרצליה ותל אביב. האימונים אישיים מיועדים לכל מטרה. אגיע לביתכם או לכל מקום שתחפצו עם כל הציוד<br /><b>איך נעשה את זה בצורה נכונה?<br /></b>אימון כושר הורים וילדים כולל התאמת תכנית בהתאם ללו"ז שלכם- אתם צריכים להתאמן מתי שנוח ומתאים לכם במסגרת מחייבת -<span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );"> כזו שתניע אתכם להתאמן על ידי מאמן כושר אישי מומלץ להורה וילד או ילדה</span></p><p>מעקב אחר תפריט התזונה שלכם- אסייע לכם להשיג את המטרות שלכם בעזרת תפריט. בעידן שבו ההורים עסוקים עד מעל לראש בעבודה וביתר מטלות החיים, עכשיו אפשר לשלב בילוי של הורים וילדים בסביבה של פעילות גופנית אשר תתרום להורה וגם לילד.ה, תוך שיפור הכושר הגופני,הקניית דוגמא אישית, ובילוי יחודי מאתגר, תוך משחקים של שיתוף פעולה וחיבור<br /><u>אימון הורה וילד</u> שיעניק לכם מחד, שיפור כושר גופני ואורח חיים בריא <span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ומאידך, בילוי זמן איכות עם הילד.ה בפעילות משותפת ואיכותית ומגבשת הכוללים אלמנטים שאפשר להרחיבם בבית באופן עצמאי . </span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size );"><b>בשלב הראשון</b></span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );"> באימון אישי הורה וילד עורך היכרות וראיון ראשוני על הילד וההורה, על תחביבים, כושר, בריאות, <a href="https://www.irispeskin.co.il/">תזונה</a></span></p><p><b>בשלב השני</b> נערוך תוכנית אימון אישי הורה וילד מגובשת הכוללת משחקים מהנים שכוללים בתוכם משחקי תנועה וכדור, ושילוב שלהם עם משקולות, רצועות, ריצה והליכה.<br />מסגרות האימון לילדים ונוער מבוססת על ניסיוני הרב בבניית תוכנית אימון ריצה כושר הכוללת מרכיבים מגוונים המעניקה לילד.ה המתאמנ.ת לשיפור כלל מרכיבי הכושר הגופני, וביחד עם ההורה צפויה מוטיבציה גבוהה, הנאה ושיפור מדדים בריאותיים, פיזיים, מוטוריים, גסה ועדינה, יכולת חשיבה, אסטרטגיה, קבלת החלטות, משמעת עצמית ואיפוק וכמובן הקניית הרגלי תזונה נכונה ומאוזנת כאורח חיים</p>"},"elements":[],"widgetType":"text-editor"},{"id":"3ab30a0","elType":"widget","settings":{"title":"למי האימון מיועד אימון אישי הורה וילד?","header_size":"h4","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"d364945","elType":"widget","settings":{"editor":"<p><span style="color: #030303;">אימוני כושר הורים וילדים על ידי </span><a style="background-color: rgba(89, 218, 122, 0.58);" href="https://www.sport4you.co.il/%d7%90%d7%99%d7%9e%d7%95%d7%9f-%d7%99%d7%9c%d7%93%d7%99%d7%9d-%d7%95%d7%a0%d7%95%d7%a2%d7%a8/">מאמן כושר אישי לילדים מומלץ</a><span style="color: #030303;"> – עבור ילדים בגילאי 6 ועד בני נוער והוריהם ויעילים להכניס כייף וזמן איכות של הורים עם ילדיהם תוך יצירת סביבה של פעילות גופנית</span><br style="color: #030303;" /><span style="color: #030303;">התורמת לילד ולהורה בהיבטים של הנאה, הקניית אורח חיים בריא, תחרויתיות קלה, יצירת שיתוף פעולה, שמירה על משקל תקין, הורדת משקל, חיטוב ושיפור כושר האישי.</span><br style="color: #030303;" /><span style="color: #030303;">המטרה היא יצירת הרגלים טובים של אורח חיים פעיל , ומתן דגש על תזונה בריאה שמתדלקת את הגוף ויצירה יחד עם ההורה מתווה של אורח חיים בריא במשפחה תוך מתן של דוגמא אישית לילד.</span><br style="color: #030303;" /><span style="color: #030303;">בעתיד יהוו אימונים שיעברו כילדים בסיס חזק ואיתן ובסבירות גבוהה שיעסוק בפעילות גופנית וישמור על תזונה מאוזנת ובריאה ומשקל תקין.</span><br style="color: #030303;" /><span style="color: #030303;">תקופת האימונים תתאפיין בהתפתחות מוטורית עדינה וגסה, העלאת רמת הביטחון העצמי והדימוי העצמי</span><br style="color: #030303;" /><span style="font-weight: bold; color: #030303;">תוכנית האימון יל ידי מאמן אישי הורה וילד </span><span style="color: #030303;">מתאימה לילדים גם לילדים ספורטאים וגם לאלו שאינם אוהבים ספורט - הכל נעשה בהדרגה תוך הדגמות מלאות, והכנת אימון שנתפר במיוחד להורה וילד.ה ספציפיים</span><br style="color: #030303;" /><span style="color: #030303;">באימון מבוגרים: הקשר והיחס בין הסתגלות עצבית וגידול כח שריר, גדל אחרי אימון כוח. זה הבסיס העיקרי לשיפור בכוח השרירי שלו.</span><br style="color: #030303;" /><span style="color: #030303;">אצל ילדים : הגידול במסת השריר הוא ממש לא המרכיב העיקרי בשיפור הכוח השריר.</span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"c2358ba","elType":"widget","settings":{"title":"עיקרי האימון ואזורי האימון הכושר","header_size":"h5","align_mobile":"center","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":28,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"9ac0d0e","elType":"widget","settings":{"editor":"<p><span style="color: #030303;">- חיזוק כושר אירובי – לב-ריאה - באמצעות אימוני ריצה בקצבים שונים ובשטח משתנה, ועל ידי שיטות שונות ומתקדמות, אימוני קיק בוקס, אימוני רצועות TRX משחקי ילדים ומשחקי כדור ותנועה</span><br style="color: #030303;" /><span style="color: #030303;">- גמישות ותנועתיות – לימוד תרגילי גמישות לשיפור תנועה והפחתת פציעות והורדת רמות סטרס, באמצעות תרגילים מעולם הסטרייצינג והיוגה</span><br style="color: #030303;" /><span style="color: #030303;">- חיזוק שרירי הגוף – כולל שרירי ליבה ושרירים עיקריים בגוף, כולל שימוש במשקולות, מתקני הפארק, </span><a style="background-color: rgba(89, 218, 122, 0.58);" href="https://www.ninja-cube.co.il/">מתקני נינג'ה ישראל</a><span style="color: #030303;">, רצועות, גומיות ושימוש בתרגילים מעולם הפילאטיס</span><br style="color: #030303;" /><span style="color: #030303;">- חיזוק יציבות הגוף – חיזוק יכולת היציבה, כיפוף יתר, גב זקוף, שיווי משקל</span><br style="color: #030303;" /><span style="color: #030303;">- העלאת ביטחון עצמי – דרך תרגילים ואמונה ביכולת הגוף, השגת מטרות, השתתפות בתחרויות</span></p><p><span style="font-weight: bold; color: #030303;">אזורי האימון</span><br style="color: #030303;" /><span style="color: #030303;">רמת השרון, המשתלה, נווה גן, תל אביב, רמת אביב, שרונה, פארק צמרת, כיכר המדינה, חוף הים, מרכז העיר, הרצליה, כפר שמריהו</span><span style="color: #030303;"><br /></span></p><p><span style="color: #030303;"><b>השאירו הודעה או צלצלו עוד היום ונתחיל בתהליך!</b></span></p>","align_mobile":"right"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"77361fc6","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},"margin_tablet":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"30","right":"30","bottom":"30","left":"30","isLinked":true},"padding_tablet":{"unit":"px","top":"40","right":"80","bottom":"40","left":"80","isLinked":false},"_timestamp_":"v1UUJmcjcvMjNHWjFyRUdDK1A3T29ZQT09","margin_mobile":{"unit":"px","top":"80","right":0,"bottom":"0","left":0,"isLinked":false},"_ha_condition_list":[{"_id":"cfd1c98"}],"__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"6575475e","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"border_border":"solid","background_bac