border_color":"#F4F4F4","border_radius":{"unit":"px","top":"19","right":"19","bottom":"19","left":"19","isLinked":true},"__dynamic__":{"link":"[elementor-tag id="c6763b7" name="internal-url" settings="%7B%22type%22%3A%22post%22%2C%22post_id%22%3A%22265%22%7D"]"},"text_shadow_text_shadow":{"horizontal":0,"vertical":0,"blur":10,"color":"rgba(7.499999999999991, 7.31912364130434, 7.31912364130434, 0.95)"},"button_text_color":"#0C0C0C","button_box_shadow_box_shadow_type":"yes","button_box_shadow_box_shadow":{"horizontal":6,"vertical":6,"blur":10,"spread":0,"color":"rgba(0,0,0,0.5)"}},"elements":[],"widgetType":"button"},{"id":"1656e9c7","elType":"widget","settings":{"editor":"<b>בניית קבוצות ריצה בארגונים  וחברות עבור מטרה או קבוצה שוטפת, כוללת אימונים שבועיים ריצה וכושר כולל ליווי שוטף עד להגעת מטרה של כל מתאמן ליעדו</b>","text_color":"#545454","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"6b83c1c9","elType":"widget","settings":{"space":{"unit":"px","size":125,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":true},{"id":"7150c5b5","elType":"section","settings":{"gap":"narrow","custom_height":{"unit":"px","size":65,"sizes":[]},"layout":"full_width","background_background":"classic","__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"36ec8f5c","elType":"column","settings":{"_column_size":100},"elements":[{"id":"811cf98","elType":"widget","settings":{"html":"<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"למי אימון הורה וילד מתאים?","acceptedAnswer":{"@type":"Answer","text":"אימון הורה וילד על ידי מאמן כושר אישי מומלץ ומתמחה באימון ילדים ומבוגרים - מתאים להורים אשר רוצים לבלות זמן איכות עם ילדיהם תוך ביצוע פעילות גופנית, מהנה, מלאת אנדרופינים, שתסייע בשיפור הכושר הגופני, אורח חיים בריא ותחזק מיומנויות אתלטיות וכושר גופני,הפחתת שעות מסך. מתאים לילדים והורים בכל רמת כושר. כנסו עכשיו לאתר למידע מקיף וערוך איפיון מתאמן - התאמת האימון לכל מתאמן לפי אופיו"}},{"@type":"Question","name":"באיזה אופן מתבצע אימון כושר הורה וילד?","acceptedAnswer":{"@type":"Answer","text":"אימון כושר הורה וילד מתבצע בכל מיני מיקומים נוחים כמו: פארק, בבית, בגינה וכולל שימוש באביזרי ספורט ומשחק מגוונים הפעילות תכלול חיזוק שרירי, חיזוק אירובי, ומשחקים משותפים ומהנים. כנסו עכשיו וקבלו פרטים על מגוון אפשרויות הבחירה עבורכם"}},{"@type":"Question","name":"כמה עולה אימון אישי הורה וילד?","acceptedAnswer":{"@type":"Answer","text":"אימון אישי הורה וילד על ידי מאמן כושר מומחה לילדים ובעל ניסיון רב באימון ילדים ומבוגרים בקבוצות ואישיים נע החל מ 200 ש\"ח ועד 300 ש\"ח\nכדי לקבל הערכה מדוייקת היכנס עכשיו לאתר ותתחילו את הדרך שלכם לכושר!"}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"088756b","elType":"widget","settings":{"tabs":[{"tab_title":"למי אימון הורה וילד מתאים?","tab_content":"<p>אימון הורה וילד על ידי מאמן כושר אישי מומלץ ומתמחה באימון ילדים ומבוגרים - מתאים להורים אשר רוצים לבלות זמן איכות עם ילדיהם תוך ביצוע פעילות גופנית, מהנה, מלאת אנדרופינים, שתסייע בשיפור הכושר הגופני, אורח חיים בריא ותחזק מיומנויות אתלטיות וכושר גופני,הפחתת שעות מסך. מתאים לילדים והורים בכל רמת כושר. כנסו עכשיו לאתר למידע מקיף וערוך איפיון מתאמן - התאמת האימון לכל מתאמן לפי אופיו</p>","_id":"ed5d480"},{"tab_title":"באיזה אופן מתבצע אימון כושר הורה וילד?","tab_content":"<p>אימון כושר הורה וילד מתבצע בכל מיני מיקומים נוחים כמו: פארק, בבית, בגינה וכולל שימוש באביזרי ספורט ומשחק מגוונים הפעילות תכלול חיזוק שרירי, חיזוק אירובי, ומשחקים משותפים ומהנים. כנסו עכשיו וקבלו פרטים על מגוון אפשרויות הבחירה עבורכם</p>","_id":"870c5cc"},{"_id":"6d0b550","tab_title":"כמה עולה אימון אישי הורה וילד?","tab_content":"<p>אימון אישי הורה וילד על ידי מאמן כושר מומחה לילדים ובעל ניסיון רב באימון ילדים ומבוגרים בקבוצות ואישיים נע החל מ 200 ש"ח ועד 300 ש"ח<br />כדי לקבל הערכה מדוייקת היכנס עכשיו לאתר ותתחילו את הדרך שלכם לכושר!</p>"}],"__globals__":{"title_color":"globals/colors?id=68f6ec0b","tab_active_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"toggle"},{"id":"4f6db0ef","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"},{"id":"badd2a5","elType":"widget","settings":{"youtube_url":"https://www.youtube.com/watch?v=qnZj0NIhzd4","vimeo_url":"https://vimeo.com/235215203","dailymotion_url":"https://www.dailymotion.com/video/x6tqhqb","yt_privacy":"yes","aspect_ratio":"219","css_filters_css_filter":"custom","start":2,"autoplay":"yes","play_on_mobile":"yes","mute":"yes"},"elements":[],"widgetType":"video"},{"id":"41bae7b","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"}],"isInner":false}],"isInner":false},{"id":"6cc063cb","elType":"section","settings":{"height":"min-height","custom_height":{"unit":"px","size":0,"sizes":[]}},"elements":[{"id":"4beb943f","elType":"column","settings":{"_column_size":100},"elements":[{"id":"252d0085","elType":"widget","settings":{"title":"מאמרים אחרונים","header_size":"h5","align":"center","typography_typography":"custom","typography_font_size":{"unit":"px","size":45,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":33,"sizes":[]},"typography_font_weight":"600","typography_text_decoration":"underline","typography_letter_spacing":{"unit":"px","size":6.8,"sizes":[]},"__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"1d962e09","elType":"widget","settings":{"classic_meta_separator":"///","classic_read_more_text":"קרא עוד »","cards_meta_separator":"•","cards_read_more_text":"קרא עוד »","full_content_meta_separator":"///","pagination_page_limit":"5","pagination_prev_label":"&laquo; הקודם","pagination_next_label":"הבא &raquo;","classic_item_ratio":{"unit":"px","size":0.37,"sizes":[]},"classic_image_width":{"unit":"%","size":86,"sizes":[]},"classic_excerpt_length":15,"text":"Load More","load_more_no_posts