}","align":"center","align_mobile":"center","_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","__globals__":{"typography_typography":"globals/typography?id=secondary"},"_ha_condition_list":[{"_id":"ceafb20"}]},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"af422e6","elType":"section","settings":{"background_background":"classic","__globals__":{"background_color":""},"_ha_condition_list":[{"_id":"56b7b59"}]},"elements":[{"id":"e243312","elType":"column","settings":{"_column_size":100,"_inline_size":null,"_ha_condition_list":[{"_id":"4e66b30"}]},"elements":[{"id":"aef2333","elType":"widget","settings":{"title":"מאמן כושר אישי","align_mobile":"center","__globals__":{"title_color":"globals/colors?id=68f6ec0b","typography_typography":"globals/typography?id=primary"},"align":"center","_ha_condition_list":[{"_id":"d58eb5c"}]},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"4415a9f","elType":"section","settings":{"background_background":"classic","_ha_condition_list":[{"_id":"e00e858"}]},"elements":[{"id":"14f468e","elType":"column","settings":{"_column_size":100,"background_background":"classic","_ha_condition_list":[{"_id":"a4e1dae"}]},"elements":[{"id":"562db06","elType":"widget","settings":{"title":"<p style="font-size: 18px; font-weight: 500; white-space: normal;"><span style="font-weight: 700;"><a href="https://www.sport4you.co.il/about-me/">תומר אלמוג</a>&nbsp; מאמן כושר אישי מומלץ, עתיר ניסיון באימון אוכלוסיות מגוונות, מאמן קבוצות מבוגרים וילדים</span><span style="color: var( --e-global-color-primary ); font-size: 22px; font-weight: 600; white-space: pre-wrap;"></span></p>","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"fdc2682","elType":"widget","settings":{"title":"אימון כושר אישי - על ידי מאמן כושר אישי","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"e25e238","elType":"widget","settings":{"editor":"<p>תופעה מבורכת שהפכה לקבועה וחשובה בהיבט של אימון נכון ומניעת פציעות -</p><p><span style="background-color: transparent; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-weight: var( --e-global-typography-text-font-weight );">ראשית, אימוני כושר אישי באמצעות המלצה על מאמן כושר אישי שידריך וינחה מתאמנים בהשגת מטרות הבריאות והכושר הגופני</span></p><p>ברור לכל שאיכות חיים שלנו וכושר גופני על כלל מרכיביו שלובים זה בזה <span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">כיום, יותר ויותר מחקרים ממליצים להתאמן בצורה יעילה על ידי</span></p><p><span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">מאמן כושר ובאופן קבוע כולנו מנסים </span><span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">להגיע לתוצאות ולהישגים, כושר גבוה והרזייה, חיטוב הגוף, השלת משקל עודף, לעלות במדרגות מבלי להתנשף,</span></p><p>אך לרוב, רובנו נכשלים בהשגת המטרה וחשוב מכך אינם מצליחים לשמור על ההישגים שהגיעו אליהם.</p><p>שנית, מאמן כושר אישי מומלץ הוא הדמות שיכול להרים, וגם, לתת את דחיפת המוטיבציה לה הייתם זקוקים</p><p><span style="color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">ובעזרתה תוכלו להגיע למטרות שהצבתם לעצמכם. </span><span style="color: var( --e-global-color-68f6ec0b ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">הגיע הזמן להרגיש צעיר ב-10 שנים ולשפר מדדי בריאות, ולא להסתכן בהתנוונות הגוף ככל שהגיל עולה.</span></p><p><span style="color: var( --e-global-color-68f6ec0b );">מאמן כושר אישי בעל ניסיון, הוא שיכול לסייע ומכיר באזור האימונים שלו את המקומות הטובים ביותר שבהם כדאי לקיים אימוני כושר אישיים,</span></p><p><span style="color: var( --e-global-color-68f6ec0b );">בהתאם לעונה, מזג האויר ושיטת האימון המותאמת למתאמנים ומיקום נוח ונעים.</span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"8ce6674","elType":"widget","settings":{"title":"שלבים בהשגת המטרה:","header_size":"h4","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":20,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"e31071d","elType":"widget","settings":{"editor":"<p>די לדחיינות! אהיה אתכם כל הדרך למטרה כולל ליווי ובקרה באופן מקצועי ומדויק, ואדאג שעכשיו ולאחר ניסיונות רבים שלא הצלחתם לממש את הפוטינציאל הגופני שלכם, סוף סוף תוכלו לעמוד במשימה שהגדרתם!! בואו נתחיל!! עוד היום, אל תנסו לדחות למחר.</p><p><span style="background-color: transparent; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-weight: var( --e-global-typography-text-font-weight );">לאחר שיחה קצרה אתחיל במלאכת הרכבת האימון האישי המתאים עבורכן - ושיטת האימון שתהיה היעילה ביותר בעבורכם.</span></p><p><span style="background-color: transparent; color: var( --e-global-color-text ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-weight: var( --e-global-typography-text-font-weight );">נתחיל להתאמן ומפה הדבר החשוב ביותר זו ההתמדה - את התוצאות לא רואים לאחר אימון אחד או אפילו שבועיים אבל זה יגיע </span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"ddcf861","elType":"widget","settings":{"editor":"<p><span style="color: var( --e-global-color-68f6ec0b ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">התהליך יכלול מעקב תזונתי עבור התזונה היומיומית והמלצות לביצוע תפריט השומר על תזונה נכונה ובריאה, מרכיב התזונה בתוכנית חשוב לא פחות ממרכיב האימון הגופני. אבנה תכנית אימונים המותאמת לך ומשלבת תרגילי כח וגמישות ובדגש טכניקה נכונה על פי המטרות שקבעת.</span></p><p><b>לדוגמא </b>- מטרת המתאמן חיטוב הגוף והורדת בטן ומשקל- כמובן שלא אתכנן עבורך תרגיל הכולל ביצוע 500 כפיפות בטן, לכן אמליץ לך לשמור באופן אדוק על התפריט התזונתי שנקבע לך יחד עם העלאת נפחי אימונים אירוביים וביצוע מדוקדק של תוכנית האימונים שאתן תוך ביצוע תרגול כח פונקציונלי בסטים עם זמנים קצרים בדופק גבוה - שבירת מיתוסים? שוב? אז הגעת למקום הנכון.. מדובר על אמצעים שיתרמו לך לירידה דרסטית באחוזי השומן ועיצוב שרירי הבטן וחיטוב השרירים והמדדים הבריאותיים כמו כן, חשוב לזכור! המטרה העיקרית היא להנות מהתהליך , לחייך, להתמיד ולעשות לעשות לעשות!<br />חשוב שתבינו ברגע שתהנו מהדרך אתם תתמידו ותצליחו! ותמיד אהיה כאן בשבילך כדי לעודד להכווין ולתת מוטיבציה נוספת ולתקן כשצריך.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"b6bc0de","elType":"widget","settings":{"title":"<h2 data-elementor-setting-key="title" data-pen-placeholder="הקלד כאן..." style="font-family: Montserrat, sans-serif; font-weight: 600; font-size: 22px;">האני מאמין שלי באימון כושר אישי</h2>","header_size":"h5","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"0019e5b","elType":"widget","settings":{"editor":"<p>על כל מתאמן למצוא מסגרת הנכונה שתסייע בהתמדה המקיימת אורח חיים בריא, ולא שינוים קיצוניים בבת אחת, לא דיאטות טרנדיות, ביחד נמצא עבורך את המקום שתוכל להתמיד בו במשך שנים רבות בתוך כל דרישות אורח חייך (תעסוקה, כושר, בריאות) נשפר מדדי בריאות וכושר.</p><p>- מחד, ברור לכל שאיכות חיים שלנו וכושר גופני על כלל מרכיביו שלובים זה בזה ויותר מחקרים ממליצים להתאמן בצורה יעילה על ידי מאמן כושר. ומאידך, רובנו מנסים להגיע לתוצאות לכושר גבוה והרזייה, אך, נכשלים בזה, אך, כאן נכנס פיתרון: מאמן כושר אישי מומלץ שיכול לתת את דחיפת המוטיבציה לה הייתם זקוקים ובעזרתה תוכלו להגיע למטרות הצבתם לעצמכם. <span style="color: var( --e-global-color-68f6ec0b ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size ); font-weight: var( --e-global-typography-text-font-weight );">גם אם כבר ניסיתם להיות חטובים ולרדת במשקל ולא הצלחתם. נקודה זו מדגיש את הצורך של השתתפות במסגרת של פעילות קבועה.  הגעתם למקום הנכון והגיע הזמן להרגיש צעיר ב-10 שנים לשפר מדדי בריאות, ולא להסתכן בהתנוונת הגוף ככל שהגיל עולה</span></p><p>- אהיה אתכם כל הדרך למטרה כולל ליווי ובקרה באופן מקצועי ומדויק, ואדאג שעכשיו ולאחר ניסיונות רבים שלא הצלחתם לממש את הפוטינציאל הגופני שלכם, סוף סוף תוכלו לעמוד במשימה שהגדרתם, בואו נתחיל! עוד היום, אל תנסו לדחות למחר.</p><p>האני מאמין שלי שעל כל מתאמן למצוא מסגרת הנכונה שתסייע בהתמדה המקיימת אורח חיים בריא, ולא שינוים קיצוניים בבת אחת , לא דיאטות טרנדיות,  ביחד נמצא עבורך את המקום שתוכל להתמיד בו במשך שנים רבות בתוך כל דרישות אורח חייך (תעסוקה, כושר, בריאות) נשפר מדדי בריאות וכושר</p>"},"elements":[],"widgetType":"text-editor"},{"id":"4d05c0d","elType":"widget","settings":{"title":"איך נעשה זאת בצורה הנכונה שתוביל לתוצאות?","header_size":"h6","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"cfd52b3","elType":"widget","settings":{"editor":"<p>בחירת מאמן כושר אישי שמתאים עבורך יכולה לסייע לך , הוא בעל ידע וניסיון ויתאים מסגרת אישית בהתאם לאפיון המתאמן.</p><p>מתחילים בשיחת פתיחה לאפיון המתאמנים - מצב בריאותי, <a href="https://wingate.org.il/%d7%97%d7%a9%d7%99%d7%91%d7%95%d7%aa-%d7%94%d7%a9%d7%99%d7%a0%d7%94-%d7%9c%d7%91%d7%99%d7%a6%d7%95%d7%a2%d7%99%d7%9d-%d7%a1%d7%a4%d7%95%d7%a8%d7%98%d7%99%d7%91%d7%99%d7%99%d7%9d/">שינה</a>, עיסוק, כושר, אורח חיים, משפחה,</p><p>משכללים את כל הנתונים ובוחרים יום ושעה המתאימים לאימון -</p><p>בדרך כלל 3 ימי אימון על מנת ליצור את השינוי זה המינימום הנדרש באופן פיזיולוגי, פחות מכך, פוגע בסיכויים להשיג את מטרותיך!</p>","text_color":"#000","__globals__":{"text_color":"globals/colors?id=68f6ec0b","typography_typography":"globals/typography?id=text"},"_ha_condition_list":[{"_id":"8474553"}]},"elements":[],"widgetType":"text-editor"},{"id":"d47b424","elType":"widget","settings":{"editor":"<p> </p><p><b style="color: var( --e-global-color-68f6ec0b ); font-family: var( --e-global-typography-text-font-family ), sans-serif; font-size: var( --e-global-typography-text-font-size );">אזורי אימון:  </b></p><p>אין ספק שכל מאמן כושר אישי מכיר באזור שלו את המקומות הטובים ביותר שבהם כדאי לקיים אימוני כושר אישיים, אם, במקום מוצל ועם הרבה מתקנים.<b><br /></b></p><p><a href="https://www.sport4you.co.il/%d7%9e%d7%90%d7%9e%d7%9f-%d7%9b%d7%95%d7%a9%d7%a8-%d7%90%d7%99%d7%a9%d7%99-%d7%9e%d7%95%d7%9e%d7%9c%d7%a5-%d7%91%d7%a8%d7%9e%d7%aa-%d7%94%d7%a9%d7%a8%d7%95%d7%9f/">מאמן כושר אישי רמת השרון</a> או מאמן כושר אישי הרצליה, מאמן כושר אישי בכפר שמריהו , מאמן כושר אישי תל אביב, מאמן כושר אישי ברמת השרון, כמו כן, מאמן כושר אישי בהרצליה מאמן כושר אישי צהלה ו<a href="https://www.sport4you.co.il/personal-trainer/%d7%9e%d7%90%d7%9e%d7%9f-%d7%90%d7%95%d7%a0%d7%9c%d7%99%d7%99%d7%9f-online/">אימון כושר אישי אונליין</a>,</p><p><b>היכן נקיים את האימונים מחוץ לבית </b>?<br />נעזר במתקני הפארקים הפזורים ברחבי העיר כגון מתקני - מתח, מקבילים, ידיים, אופני כושר, ספת בטן, מכשיר פרפר חזה, ספסלים, עצים, סולמות בשיטת אימון נינג'ה ישראל ועוד.. זאת ועוד, האימונים מתקיימים בבית הלקוח או בכל מקום מתאים אחר - אימון אישי עד בית הלקוח / מאמן אישי בפארק /  מאמן אישי בפארק הירקון תל אביב יפו / מאמן אישי חוף הים הרצליה תל אביב /מאמן אישי OUTDOOR אאוטדור / מאמן אישי בבית הלקוח אימון כושר אישי בבית הלקוח</p>","_ha_condition_list":[{"_id":"96cf3bf"}],"__globals__":{"text_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"68606291","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},"margin_tablet":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"30","right":"30","bottom":"30","left":"30","isLinked":true},"padding_tablet":{"unit":"px","top":"40","right":"80","bottom":"40","left":"80","isLinked":false},"_timestamp_":"v1UUJmcjcvMjNHWjFyRUdDK1A3T29ZQT09","margin_mobile":{"unit":"px","top":"80","right":0,"bottom":"0","left":0,"isLinked":false},"_ha_condition_list":[{"_id":"cfd1c98"}],"__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"503dfc25","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0"