}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":14},"_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.7,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":1.4,"sizes":[]},"size":"small"},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"25c31dc4","elType":"section","settings":{"layout":"full_width","background_background":"classic","background_color":"#59DA7A94"},"elements":[{"id":"3f40e9df","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic"},"elements":[{"id":"4c83869c","elType":"widget","settings":{"title":"מאמן כושר אישי <br>ברמת השרון","align":"center","title_color":"#040405","__globals__":{"typography_typography":"globals/typography?id=primary"}},"elements":[],"widgetType":"heading"},{"id":"177b0f0","elType":"widget","settings":{"title":"תומר אלמוג מאמן כושר אישי מומלץ ברמת השרון","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","__globals__":{"title_color":"globals/colors?id=68f6ec0b"},"header_size":"h3","typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"2975a302","elType":"widget","settings":{"editor":"<p>פרופיל מאמן לימוד נעים - 10 אימונים ותראו את השינוי<br />מאמן כושר אישי ברמת השרון ואימונים אישיים מיועד לכל מטרה. אגיע לביתכם או לכל מקום שתחפצו עם כל הציוד המקצועי והמתקדם ביותר<br /><b>איך נעשה את זה בצורה נכונה?<br /></b>התאמת תכנית בהתאם ללו"ז שלכם- אתם צריכים להתאמן מתי שנוח ומתאים לכם במסגרת מחייבת - כזו שתניע אתכם להתאמן<br />בקרה אחר תפריט התזונה שלכם- אני אעזור ואסייע לכם להשיג את המטרות שלכם בעזרת תפריט.<br />בניית תכנית האימונים הנכונה ביותר עבורכם- אנחנו נעבוד לפי תכנית מסודרת בה נעקוב כל שבוע אחר ההתקדמות שלכם בכל האספקטים.<br />לווי רציף - אדבר איתכם על בסיס קבוע ואדאג שהפעם אתם תתמידו בתהליך ותראו את השינוי!</p><p>אם קשה לך להתמיד באימונים – אני אסייע לך להפוך את האימון הגופני לדרך חיים!<br />אם אינך רואה תוצאות – אני אראה לך את הדרך לאימון יעיל ואפקטיבי!<br />אם אין לך זמן להתאמן – אני מגיע לביתך ומאמן אותך לתוצאות במינימום השקעת זמן!</p>","text_color":"#030303","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"fe7347b","elType":"widget","settings":{"title":"אזורי האימונים ברמת השרון","header_size":"h4","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"67620a6","elType":"widget","settings":{"editor":"<p>קיימים אזורים בהם מאמן כושר אישי מומלץ ברמ השרון יאמן:</p><p>פארק הנביאים , פארק הנצח רמת השרון , הכפר הירוק, אלכסנדרוני,&nbsp; המערבית , נווה גן , נווה רום, צהלה, המשתלה,&nbsp; קאנטרי קלאב רמת השרון , ספורטיב, ספייס.<br>אזורי האימון כוללים משטחי ריצה שונים, תחנות כושר הכוללים מתקני כושר של מתח, ספות בטן, מקבילים, פרפר חזה, פשיטת רגליים, ואופני כושר,</p><p>&nbsp;כמובן ספסלים ועצים המעניקים תחושת קרירות לאימון כושר רמת השרון על ידי מאמן כושר אישי רמת השרון שמביא איתו את האביזרים המתאימים לכל לוקיישן.</p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">אני משמש גם כמאמן ריצה ברמת השרון תל אביב והרצליה וב</span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">קבוצת ריצה מתחילים רמת השרון, קבוצת ריצה רמת השרון וקבוצות ילדים ונוער.</span></p>","__globals__":{"text_color":"globals/colors?id=68f6ec0b"},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"80076cf","elType":"widget","settings":{"title":"מסלולי ריצה ברמת השרון","header_size":"h5","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"a7998fd","elType":"widget","settings":{"editor":"<p>כמאמן ריצה רמת השרון אני ממליץ לרוץ בעיקר על 3 מסלולי ריצה:&nbsp; &nbsp;</p>
<p><b style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size );">- הראשון </b><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">מתחיל באצטדיון האתלטיקה ברחוב הזית ליד תיכון רוטברג וממנו דרך פארק הנצח, רחוב ויצמן, עיריית רמת השרון, רחוב ביאליק, שביל השדות, עד מחנה גלילות חזרה - כ- 10 ק"מ.&nbsp;&nbsp;</span></p>
<p><b style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size );">- מסלול שני</b><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">- מתחיל ברחוב הזית ונכנס לשדות מאחורי מרכז הטניס ברמת השרון ומהווה אימון ריצה רמת השרון למתחילים בצורה הטובה ביותר הכולל שטח מגוון , עליות ארוכות וקצרות, שטח חולי וכורכר.&nbsp;</span></p>
<p><b>- מסלול השלישי</b> ברחובות העיר ברובעים מורשה, הדר, נווה רום, הכפר הירוק, נווה גן, המשתלה כולל עליות ארוכות מאוד, וירידות ארוכות, מדרכות אספלט ואבנים משתלבות אקרשטיין.</p>
<p>ארועי ספורט המתקיימים ברמת השרון ובסביבה- אליהם אני מכין את מתאמניי&nbsp; : מירוץ אייל ברמת השרון . אייל היה חבר ילדות שלי והיה אדם, ספורטאי ורץ מצטיין, התאמנו יחדיו ברצי רמת השרון.</p><p>לרוב אני מכין את מתאמני לאחת מתחרויות <a href="https://www.sport4you.co.il/%d7%9c%d7%95%d7%97-%d7%aa%d7%97%d7%a8%d7%95%d7%99%d7%95%d7%aa-%d7%a8%d7%99%d7%a6%d7%94-%d7%a2%d7%93%d7%9b%d7%a0%d7%99-%d7%91%d7%90%d7%a8%d7%a5-%d7%95%d7%91%d7%a2%d7%95%d7%9c%d7%9d/">מלוח התחרויות</a> והבולטות שבהן&nbsp;<a href="https://www.tlvmarathon.co.il/MenuDefault.aspx?id=7820">מרתון תל אביב</a>, <a href="https://www.realtiming.co.il/events/1033">מרוץ הרצליה</a>, <a href="https://jerusalem-marathon.com/">מרתון ירושלים</a>, <a href="https://www.mountain2valley.org/">מרוץ הר לעמק</a>&nbsp;ועוד תחרויות רבות&nbsp;</p>","__globals__":{"text_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"700f824c","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},"margin_tablet":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"30","right":"30","bottom":"30","left":"30","isLinked":true},"padding_tablet":{"unit":"px","top":"40","right":"80","bottom":"40","left":"80","isLinked":false},"_timestamp_":"v1UUJmcjcvMjNHWjFyRUdDK1A3T29ZQT09","margin_mobile":{"unit":"px","top":"80","right":0,"bottom":"0","left":0,"isLinked":false}},"elements":[{"id":"7c0facbc","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin_tablet":{"unit":"px","top":"0","r