}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":19},"_margin_mobile":{"unit":"px","top":"60","right":"0","bottom":"40","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.2,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":-0.7,"sizes":[]}},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"2478692a","elType":"section","settings":{"layout":"full_width","background_background":"classic","background_color":"#59DA7A94"},"elements":[{"id":"72ebb84a","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic"},"elements":[{"id":"6c345e9b","elType":"widget","settings":{"title":"אימון כושר אישי  לגיל השלישי","align":"center","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":28,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600"},"elements":[],"widgetType":"heading"},{"id":"e45cca4","elType":"widget","settings":{"title":"אימון כושר אישי בגיל השלישי - גיל הזהב","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"73b4df2f","elType":"widget","settings":{"editor":"<p>אימון כושר אישי למבוגרים בגיל השלישי על ידי מאמן כושר אישי מומלץ לגיל השלישי - מתמחה בתרגילים יעודיים ובעל רגישות מתאימה לאוכלוסייה הייחודית והחשובה </p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ככל שעובר הזמן האוכלוסייה הולכת ומתבגרת ומנגד עולה תוחלת החיים. בישראל תוחלת החיים הממוצעת היא גבוהה ועוברת גיל 80 אך מנגד ישנה </span><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">תחלואה רבה.</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">בימינו אלו גיל הזהב והגיל השלישי הוא גיל פעיל, חברתי, תוסס ובעל יכולות טכנולוגיות עם זאת גם כזה הדורש פעילויות פנאי וכושר.</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ממחקרים רבים שבוצעו- עולה שאימון נכון ומבוקר בגיל השלישי יכול להפחית סיכונים למחלות ואף לסייע בשיפור רמת החיים,</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">הפחתה בנפילות, ומנגד היכולת לקום מנפילה, הארכת תוחלת החיים, פחות מחלות, ותנועה חופשית טובה יותר.</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">במקום להיכנע לחוסר פעילות וירידה במצב הרוח והביטחון העצמי- פשוט מתחילים להתאמן.</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ניתן להתאמן בבית או בחצר, בפארק הסמוך, חדר כושר או כל מקום נח למתאמן.</span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ניתן לשלב גם </span><a style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); background-color: rgba(89, 218, 122, 0.58);" href="https://www.sport4you.co.il/%d7%9e%d7%90%d7%9e%d7%9f-%d7%9b%d7%95%d7%a9%d7%a8-%d7%90%d7%99%d7%a9%d7%99-%d7%90%d7%95%d7%a0%d7%9c%d7%99%d7%99%d7%9f-online/">אימוני אונליין</a><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );"> דרך מסך הטלוויזיה או המחשב. מ</span><a style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); background-color: rgba(89, 218, 122, 0.58);" href="https://www.health.gov.il/Subjects/Geriatrics/HealthPromotionAndPreventiveMedicine/Pages/exercise.aspx">שרד הבריאות פרסם מספר ניירות עמדה</a><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );"> לגבי אוכלוסיה זאת, והחשיבות העצומה בביצוע אימוני התנגדות</span></p><p><b>אימוני התנגדות פשוט יכולים להציל את הקרובים שלכם</b>.<br />אימון כושר אישי למבוגרים בגיל השלישי הוא חיוני - מדובר ממש בבשורה שיש להעביר לכל מי שהגיע לגיל זה -</p><p><a href="https://www.ynet.co.il/articles/0,7340,L-5267684,00.html">חייבים להתחיל להתאמן ולחזק את השרירים</a> <span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ולמנוע מסת שריר ולחזק את הגוף כנגד נפילות</span></p><p>למתאמנים עם מאמן כושר אישי לגיל הזהב גיל השלישי בעל ניסיון רב, ורגישות לעקרונות המיוחדים של אוכלוסיית הגילאים הזו.</p>","text_color":"#030303","__globals__":{"typography_typography":"globals/typography?id=accent"}},"elements":[],"widgetType":"text-editor"},{"id":"ae8720b","elType":"widget","settings":{"title":"מה כולל תהליך האימון האישי לגיל השלישי","header_size":"h4","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","typography_font_size_mobile":{"unit":"px","size":18,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"f3a517c","elType":"widget","settings":{"editor":"<p><b><u>בשלב הראשון</u></b>: ראיון ותשאול אודות אורח חייו של המתאמן, יכולותיו, מגבלותיו, בדיקת משקל, זוויות תנועה וכח ותזונה.<br /><b><u>שלב שני</u></b>: יצאנו לדרך ולשלב האימונים הראשון - בעיקר אירובי קל ואימוני התנגדות, שיווי משקל וכח, והכל עם אביזרים מגוונים ומתקדים ובקרה רציפה הן על אימוני הכושר והן על התזונה.<br /><b><u>שלב שלישי</u></b> - עצמאות המתאמן בביצוע תרגילים וביצוע פעולות יומיומיות בסיסיות ומורכבות יותר באופן עצמאי.<br />תהליך האימון יקנה למתאמן ולקרוביו להבין את היסודות החשובים באימון הכושר והחשיבות ובמטרות ביצוע התרגילים, כל זה יאפשר ביצוע עצמאי ונכון של התרגילים בטכניקה היעילה ביותר.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"715c217","elType":"widget","settings":{"title":"כללי הזהב לאימון בגיל השלישי","header_size":"h5","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":20,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"31123c1","elType":"widget","settings":{"editor":"<p>- לימוד הטכניקה הבסיסית של התרגילים המרכיבים את האימון - מומלץ שתדאגו להתאמן תחת פיקוחו של מאמן כושר מומלץ, <br />המתמחה בהעברת אימוני ריצה למתאמנים בגיל הזהב שינחה ויחזק את הטכניקה לביצוע תרגילים - דבר שימנע פציעות.<br />- ביצוע חימום, הרפיה ומנוחה בכל אימון בסבלנות ובטכניקה נכונה<br />- ביצוע האימון ומשך האימון והן את דרגת הקושי של האימון יעלו ויאתגרו באופן הדרגתי, כשמתינות היא מילת המפתח.<br />- לימוד קרוביו של המתאמן אודות ביצוע נכון של התרגיל<br />-שימוש באביזרי התנגדות הינו קריטי לשמירה על מסת השריר והנעה להיפרטרופיה שרירית שתאפשר התקדמות הגוף וחיזוקו.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"f6a164c","elType":"widget","settings":{"title":"3 תרגילים לחיזוק שרירי הרגליים לגיל השלישי","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","header_size":"h5","typography_font_size_mobile":{"unit":"px","size":17,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"8a0d458","elType":"widget","settings":{"editor":"<p>- לקום מהכסא ולשבת - ניתן לביצוע עם משקל קל. לאחר מכן ניתן להוסיף התנגדות קלה באמצעות גומיית אימון רכה. בשלב האחרון ניתן להוסיף משקולות חופשיות<br />- חיזוק שרירי תאומים תמיכה הגוף בעמידה כנגד הקיר ולעלות על קצות האצבעות ולרדת, בשלב הבא שימוש בהתנגדות משקל גבוה יותר ויותר<br />- תרגול הרמות אגן - תוך העלאת אגן מעלה ומטה והצידה, אפשרות לעשות תוך כדי עמידה על רגל אחת, בשלב הבא שימוש בגומיות התנגדות</p>"},"elements":[],"widgetType":"text-editor"},{"id":"22f3b07","elType":"widget","settings":{"title":"אזורי האימון לגיל השלישי","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":22,"sizes":[]},"typography_font_weight":"600","header_size":"h6","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":19,"sizes":[]}},"elements":[],"widgetType":"heading"},{"id":"327c258","elType":"widget","settings":{"editor":"<p>רמת השרון, המשתלה, נווה גן, תל אביב, רמת אביב, שרונה, פארק צמרת, כיכר המדינה, חוף הים, מרכז העיר, הרצליה, כפר שמריה, בבית, בפארקים או בחוף הים, הרצליה פיתוח, הרצליה הירוקה<br />האימונים יכולים להתקיים בפארקים, אצטדיון אתלטיקה, חדר כושר, בבית, בחצר הבית, חוף הים - ניתן ליצור קשר בהמשך, ולעיין במסלולים הנוספים שאני מציע למתאמנים מכל הגילאים ורמות הכושר</p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"1c7b6dc","elType":"section","settings":{"custom_height":{"unit":"px","size":1388},"background_background":"classic","background_image":{"id":1146,"url":"http://www.sport4you.co.il/wp-content/uploads/2019/10/3-2-1.jpg"},"background_position":"center center","background_size":"cover","background_overlay_title":"","background_overlay_background":"classic","background_overlay_opacity":{"unit":"px","size":"0.7"},"padding":{"unit":"px","top":"80","right":"80","bottom":"80","left":"80","isLinked":true},"margin_tablet":{"unit":"px","top":"","right":0,"bottom":"","left":0,"isLinked":true},"padding_mobile":{"unit":"px","top":"30","right":"30","bottom":"30","left":"30","isLinked":true},"padding_tablet":{"unit":"px","top":"40","right":"80","bottom":"40","left":"80","isLinked":false},"_timestamp_":"v1UUJmcjcvMjNHWjFyRUdDK1A3T29ZQT09","margin_mobile":{"unit":"px","top":"80","right":0,"bottom":"0","left":0,"isLinked":false},"_ha_condition_list":[{"_id":"cfd1c98"}],"__globals__":{"background_color":""}},"elements":[{"id":"538c07e2","elType":"column","settings":{"_column_size":100,"_inline_size":null,"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true},"border_border":"solid","background_background":"classic","background_color":"#A0CFB8","_ha_condition_list":[{"_id":"456ba75"}]},"elements":[{"id":"5ca4206d","elType":"widget","settings":{"title":"להסבר על מסלולי האימון - השאירו פרטים","size":"large","align":"center","title_color":"#030303","typography_typography":"custom","typography_font_size":{"unit":"px","size":26},"typography_font_family":"Roboto Condensed","typography_font_style":"italic","typography_letter_spacing":{"unit":"px","size":3