rder_color":"#F4F4F4","border_radius":{"unit":"px","top":"19","right":"19","bottom":"19","left":"19","isLinked":true},"__dynamic__":{"link":"[elementor-tag id="c6763b7" name="internal-url" settings="%7B%22type%22%3A%22post%22%2C%22post_id%22%3A%22265%22%7D"]"},"text_shadow_text_shadow":{"horizontal":0,"vertical":0,"blur":10,"color":"rgba(7.499999999999991, 7.31912364130434, 7.31912364130434, 0.95)"},"button_text_color":"#0C0C0C","button_box_shadow_box_shadow_type":"yes","button_box_shadow_box_shadow":{"horizontal":6,"vertical":6,"blur":10,"spread":0,"color":"rgba(0,0,0,0.5)"}},"elements":[],"widgetType":"button"},{"id":"5a71a8ce","elType":"widget","settings":{"editor":"<b>בניית קבוצות ריצה בארגונים  וחברות עבור מטרה או קבוצה שוטפת, כוללת אימונים שבועיים ריצה וכושר כולל ליווי שוטף עד להגעת מטרה של כל מתאמן ליעדו</b>","text_color":"#545454","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"c9f5c79","elType":"widget","settings":{"space":{"unit":"px","size":125,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":true},{"id":"5b2925ce","elType":"section","settings":{"background_background":"classic","__globals__":{"background_color":""}},"elements":[{"id":"3b662d4","elType":"column","settings":{"_column_size":100},"elements":[{"id":"70e75083","elType":"widget","settings":{"html":"<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"כמה עולה מאמן כושר אישי המתמחה בגיל השלישי?","acceptedAnswer":{"@type":"Answer","text":"מאמן כושר אישי המתמחה בגיל השלישי הוא דמות מאוד  חשובה עבור אוכלוסיה זאת. ישנה חשיבות רבה בחירת מאמן מוסמך ומומחה לגילים אלו ובהתאמת תרגילים למתאמן ספציפי כדי לחזק אותו ומאידך לא לגרום לו לפציעות. העלות משתנה בהתאם למספר האימונים השבועי / חודשי, מיקום האימונים, אביזרים, סוג האימון ועוד. כנסו לאתר לאפיון מלא של עלות האימון"}},{"@type":"Question","name":"למי מתאים אימון עם מאמן כושר אישי למבוגרים?","acceptedAnswer":{"@type":"Answer","text":"אימון כושר אישי מתאים לאוכלוסיית הגיל השלישי - אשר ממש יש חובה על יקיריהם לדאוג להם לאימון גופני שוטף וקבוע. האימון מתאים לקשת רחבה של אוכלוסיה - אך ישנפ כאלו עם בעיות רפואיות אשר יכולות למנוע אימון אישי במתכונת זאת.ראו פירוט מלא עם ישנה התאמה וקבלו איפיון מלא"}},{"@type":"Question","name":"אילו מיקומים מתאימים לאימון למבוגרים בגיל השלישי?","acceptedAnswer":{"@type":"Answer","text":"ניתן לקיים אימון כושר אישי במספר רב של מיקומים, שיהיה נוח למתאמנים בגיל השלישי -בבית, ים, אצטדיון, פארק, במרפסת, בחדר כושר ובהרבה מקומות נוספים. כנסו לאתר לאפיון מקום האימון המתאים ביותר"}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"3adde3c7","elType":"widget","settings":{"tabs":[{"tab_title":"כמה עולה מאמן כושר אישי המתמחה בגיל השלישי?","tab_content":"<p>מאמן כושר אישי המתמחה בגיל השלישי הוא דמות מאוד חשובה עבור אוכלוסיה זאת. ישנה חשיבות רבה בחירת מאמן מוסמך ומומחה לגילים אלו ובהתאמת תרגילים למתאמן ספציפי כדי לחזק אותו ומאידך לא לגרום לו לפציעות. העלות משתנה בהתאם למספר האימונים השבועי / חודשי, מיקום האימונים, אביזרים, סוג האימון ועוד. כנסו לאתר לאפיון מלא של עלות האימון</p>","_id":"229e5f7"},{"tab_title":"למי מתאים אימון עם מאמן כושר אישי למבוגרים?","tab_content":"<p>אימון כושר אישי מתאים לאוכלוסיית הגיל השלישי - אשר ממש יש חובה על יקיריהם לדאוג להם לאימון גופני שוטף וקבוע. האימון מתאים לקשת רחבה של אוכלוסיה - אך ישנפ כאלו עם בעיות רפואיות אשר יכולות למנוע אימון אישי במתכונת זאת.ראו פירוט מלא עם ישנה התאמה וקבלו איפיון מלא</p>","_id":"3867294"},{"tab_title":"אילו מיקומים מתאימים לאימון למבוגרים בגיל השלישי?","tab_content":"<p>ניתן לקיים אימון כושר אישי במספר רב של מיקומים, שיהיה נוח למתאמנים בגיל השלישי -בבית, ים, אצטדיון, פארק, במרפסת, בחדר כושר ובהרבה מקומות נוספים. כנסו לאתר לאפיון מקום האימון המתאים ביותר</p>","_id":"e3be0ad"}],"title_color":"#000","title_typography_typography":"custom","title_typography_font_family":"Montserrat","