"border_color":"#F4F4F4","border_radius":{"unit":"px","top":"19","right":"19","bottom":"19","left":"19","isLinked":true},"__dynamic__":{"link":"[elementor-tag id="c6763b7" name="internal-url" settings="%7B%22type%22%3A%22post%22%2C%22post_id%22%3A%22265%22%7D"]"},"text_shadow_text_shadow":{"horizontal":0,"vertical":0,"blur":10,"color":"rgba(7.499999999999991, 7.31912364130434, 7.31912364130434, 0.95)"},"button_text_color":"#0C0C0C","button_box_shadow_box_shadow_type":"yes","button_box_shadow_box_shadow":{"horizontal":6,"vertical":6,"blur":10,"spread":0,"color":"rgba(0,0,0,0.5)"}},"elements":[],"widgetType":"button"},{"id":"7a357f84","elType":"widget","settings":{"editor":"<b>בניית קבוצות ריצה בארגונים  וחברות עבור מטרה או קבוצה שוטפת, כוללת אימונים שבועיים ריצה וכושר כולל ליווי שוטף עד להגעת מטרה של כל מתאמן ליעדו</b>","text_color":"#545454","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":14,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"7e0bb4f5","elType":"widget","settings":{"space":{"unit":"px","size":125,"sizes":[]}},"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":true},{"id":"71b36e71","elType":"section","settings":{"background_background":"classic","__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"6c7905a9","elType":"column","settings":{"_column_size":100},"elements":[{"id":"61839c59","elType":"widget","settings":{"html":"<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"מה זה תוכנית אימונים ריצה?","acceptedAnswer":{"@type":"Answer","text":"תוכנית אימונים ריצה מבית היוצר של תומר אלמוג, מאמן ריצה בעל ניסיון רב ורץ בכיר בעצמו, מעניק לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, ולהגיע להישגים באופן עצמאי. התוכנית מועברת אליכם באמצעות אפליקציה ייעודית עם תכנון שבועי/יומי וכוללת בקרה שוטפת, טיפים והדרכה להכנה לתחרויות, אימונים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם"}},{"@type":"Question","name":"האם תוכנית אימונים ריצה מתאימה לכל הרמות?","acceptedAnswer":{"@type":"Answer","text":"תוכנית אימונים ריצה בדגש על מרכיבי ריצה ואימוני כח כולל הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה בעל הכשרות רבות וניסיון עצום יעניק לכם את היכולת להגיע למטרה שלכם - גם אם מדובר במטרה של להתחיל לרוץ מ אפס או מטרות של לרוץ אולטרה מרתון במון בלאן.  כנסו לאתר וקבלו איפיון המתאים עבורכם"}},{"@type":"Question","name":"תוכנית אימונים ריצה מחיר?","acceptedAnswer":{"@type":"Answer","text":"מחיר תוכנית אימונים ריצה אינו גבוה ומעניקה לכם את תחושת המסוגלות והאמונה בגוף שלכם שתתבטא בכל היבטי החיים, תוכלו להגיע ליעדים שלכם עם ליווי מלא ועזרה בכל פרמטר. העלויות לתוכנית אימונים ריצה נעה החל מ 250 ש\" לחודש. כנסו לאתר וקבלו הצעת מחיר."}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"2e4ce52c","elType":"widget","settings":{"tabs":[{"tab_title":"מה זה תוכנית אימונים ריצה?","tab_content":"<p>תוכנית אימונים ריצה מבית היוצר של תומר אלמוג, מאמן ריצה בעל ניסיון רב ורץ בכיר בעצמו, מעניק לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, ולהגיע להישגים באופן עצמאי. התוכנית מועברת אליכם באמצעות אפליקציה ייעודית עם תכנון שבועי/יומי וכוללת בקרה שוטפת, טיפים והדרכה להכנה לתחרויות, אימונים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם</p>","_id":"229e5f7"},{"tab_title":"האם תוכנית אימונים ריצה מתאימה לכל הרמות?","tab_content":"<p>תוכנית אימונים ריצה בדגש על מרכיבי ריצה ואימוני כח כולל הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה בעל הכשרות רבות וניסיון עצום יעניק לכם את היכולת להגיע למטרה שלכם - גם אם מדובר במטרה של להתחיל לרוץ מ אפס או מטרות של לרוץ אולטרה מרתון במון בלאן. כנסו לאתר וקבלו איפיון המתאים עבורכם</p>","_id":"3867294"},{"tab_title":"תוכנית אימונים ריצה מחיר?","tab_content":"<p>מחיר תוכנית אימונים ריצה אינו גבוה ומעניקה לכם את תחושת המסוגלות והאמונה בגוף שלכם שתתבטא בכל היבטי החיים, תוכלו להגיע ליעדים שלכם עם ליווי מלא ועזרה בכל פרמטר. העלויות לתוכנית אימונים ריצה נעה החל מ 250 ש" לחודש. כנסו לאתר וקבלו הצעת מחיר.</p>","_id":"e3be0ad"}],"title_color":"#000","title_typography_typography":"custom","title_typography_font_family":"Montserrat","title_typography_font_size":{"unit":"px","size":28,"sizes":[]},"title_typography_font_size_mobile":{"unit":"px","size":25,"sizes":[]},"title_typography_font_weight":"600","content_color":"#000","__globals__":{"title_color":"globals/colors?id=68f6ec0b","content_color":"globals/colors?id=68f6ec0b","tab_active_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"toggle"}],"isInner":false}],"isInner":false},{"id":"21ee46f7","elType":"section","settings":{"gap":"narrow","custom_height":{"unit":"px","size":65,"sizes":[]},"layout":"full_width","background_background":"classic","__globals__":{"background_color":"globals/colors?id=ebcc3e8"}},"elements":[{"id":"288e03c3","elType":"column","settings":{"_column_size":100},"elements":[{"id":"6f29f6a6","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"},{"id":"635fdb41","elType":"widget","settings":{"youtube_url":"https://www.youtube.com/watch?v=qnZj0NIhzd4","vimeo_url":"https://vimeo.com/235215203","dailymotion_url":"https://www.dailymotion.com/video/x6tqhqb","yt_privacy":"yes","aspect_ratio":"219","css_filters_css_filter":"custom","start":2,"autoplay":"yes","play_on_mobile":"yes","mute":"yes"},"elements":[],"widgetType":"video"},{"id":"2b32b3a6","elType":"widget","settings":{"text":"מפריד"},"elements":[],"widgetType":"divider"}],"isInner":false}],"isInner":false},{"id":"a787e6d","elType":"section","settings":{"height":"min-height","custom_height":{"unit":"px","size":0,"sizes":[]}},"elements":[{"id":"74c9ccb5","elType":"column","settings":{"_column_size":100},"elements":[{"id":"8206630","elType":"widget","settings":{"title":"מאמרים אחרונים","header_size":"h5","align":"center","typography_typography":"custom","typography_font_size":{"unit":"px","size":45,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":33,"si