}","align":"center","align_mobile":"center","typography_font_size_mobile":{"unit":"px","size":15},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"_padding_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"title_color":"#ffffff","typography_line_height_mobile":{"unit":"em","size":1.7,"sizes":[]},"typography_letter_spacing_mobile":{"unit":"px","size":1.4,"sizes":[]},"size":"small","_ha_condition_list":[{"_id":"db44aa6"}]},"elements":[],"widgetType":"heading"}],"isInner":false}],"isInner":false},{"id":"32f7ec07","elType":"section","settings":{"background_background":"classic","_ha_condition_list":[{"_id":"609914a"}]},"elements":[{"id":"6c31b83e","elType":"column","settings":{"_column_size":100,"_inline_size":null,"background_background":"classic","_ha_condition_list":[{"_id":"5d160a6"}]},"elements":[{"id":"47a8aea8","elType":"widget","settings":{"title":"אימון ריצה למתחילים ","align":"center","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":26,"sizes":[]},"typography_font_weight":"600","typography_letter_spacing":{"unit":"px","size":0.3,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":20,"sizes":[]},"_ha_condition_list":[{"_id":"8614fdb"}]},"elements":[],"widgetType":"heading"},{"id":"ba2127a","elType":"widget","settings":{"title":"תוכנית אימוני ריצה למתחילות ומתחילים","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"600","__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"436daa0","elType":"widget","settings":{"editor":"<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">תכנית אימון ריצה למתחילים היא תוכנית מקצועית אישית אונליין ONLINE מקוונת ב"שלט רחוק" הכוללת בקרה בעזרת אפליקצית ריצה חכמה.</span></p>
<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">מנסיוני הרב, החשוב ביותר עבור רצים אלו זה הפניות ומענה מהיר לשאלות הנוגעות לתוכנית האימונים, האופן בו יש לבצעם, והשינויים שנדרשים בהם - ואני מעניק את הפיתרון למענה בצורת זמינות ומענה תדיר דרך ווצאפ, הטלפון והאפליקציה.</span></p>
<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">&nbsp;מדובר באפליקציה מתקדמת שתעניק בקרה באופן שוטף אחר הביצועים שלך ודרכה אבצע ניתוח מעמיק של רמת הכושר והריצה שלך.&nbsp;</span></p>
<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">תוכנית אימון ריצה למתחילים כוללת אימונים מדויקים, אישיים ומותאמים בדיוק ליכולת הנוכחית ולקצבי הריצה שלך ותתחשב בכל מארג החיים שלכם הכוללים:</span></p>
<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">&nbsp;משפחה, ילדים, טיולים, שינה, עבודה, תחביבים, נסיעות לחו"ל ועוד..</span></p>","align":"right","text_shadow_text_shadow":{"horizontal":0,"vertical":0,"blur":12,"color":"rgba(0,0,0,0.3)"},"__globals__":{"text_color":"globals/colors?id=68f6ec0b","typography_typography":""},"text_color":"#000","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"},{"id":"5443221","elType":"widget","settings":{"title":"תוכנית אימון ריצה למתחילים .ות למי היא מתאימה?","header_size":"h3","align":"right","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"600","typography_letter_spacing":{"unit":"px","size":0.3,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":17,"sizes":[]},"_ha_condition_list":[{"_id":"8614fdb"}]},"elements":[],"widgetType":"heading"},{"id":"a69a6ef","elType":"widget","settings":{"editor":"<p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">ברוכים הבאים לעולם הריצה - </span>בניית תוכנית אימון ריצה למתחילים - תוכנית המיועדת לכל מי שחפץ לרוץ באופן קבוע</p><p>אך עד כה לא הצליח להתמיד באופן בכך (יש שיקראו לזה מבטטת כורסה ל 5 ק"מ)  או שרצו לפני המון שנים והפסיקו.</p><p>תוכלו ללחוץ בלינק או להשאיר בקשה ביצירת קשר בדף זה, ותקבלו לאימייל תוכנית גנרית כללית חינם:</p><p>** תוכנית ריצה למתחילים 5 ק"מ או** <span style="background-color: rgba(89, 218, 122, 0.58);"><a href="https://www.sport4you.co.il/%d7%aa%d7%95%d7%9b%d7%a0%d7%99%d7%aa-%d7%90%d7%99%d7%9e%d7%95%d7%a0%d7%99%d7%9d-10-%d7%a7%d7%9e/">תוכנית אימונים ריצה למתחילים 10 ק"מ</a></span></p><p><span style="font-family: var( --e-global-typography-accent-font-family ), sans-serif; font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight );">תוכניות אלו כוללות הכנה ל<a href="https://www.realtiming.co.il/events/1033">מרוץ 10 קמ</a> (ההמלצה למתחילים ממש לבצע תוכנית אימונים ריצה 5 ק"מ). </span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">חשוב לי לציין שתוכנית אימון זו אינה מתחשבת בנתונים האישיים שלך או ביכולת הספציפית שלך,</span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;"> אלה יכולים להתבטא בנתוני הפתיחה שונים כגון:</span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">רמת הכושר שונה, משקל, היסטוריית עיסוק בספורט, מצב רפואי, עיסוק, והיכולת שלך לפנות זמן עבור אימונים.</span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">אך אל דאגה היא מספקת לצעדים הראשונים שלכם בעולם הריצה כמובן, שחשוב לא לדחוק בגוף ולעבוד בצורה הדרגתית,</span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;"> ההתקדמות היא אישית ויש מתאמנים שיתקדמו מהר יותר, אך אל דאגה! אם השקעת והתאמנת - תראו שינוי מדהים!</span></p><p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;"> בחרו מטרה ותרוצו עליה. </span><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">לחצו ותבחרו תחרות מתאימה ב<a href="https://www.sport4you.co.il/%d7%9c%d7%95%d7%97-%d7%aa%d7%97%d7%a8%d7%95%d7%99%d7%95%d7%aa-%d7%a8%d7%99%d7%a6%d7%94-%d7%a2%d7%93%d7%9b%d7%a0%d7%99-%d7%91%d7%90%d7%a8%d7%a5-%d7%95%d7%91%d7%a2%d7%95%d7%9c%d7%9d/">לוח תחרויות ריצה מעודכן</a>. </span></p>","align":"right","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"500","__globals__":{"text_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"text-editor"},{"id":"0362eeb","elType":"widget","settings":{"image":{"url":"https://www.sport4you.co.il/wp-content/uploads/2019/11/-ללא-שם-e1573557536222.jpg","id":2550,"alt":"אימון אישי אונליין תוכנית אימון כתובה ובווידאו ובתמונות","source":"library"},"title_text":"לחצו על תוכנית האימונים אונליין המתאימה לכם וקבלו אותה ללא עלות","description_text":"","image_border_radius":{"unit":"px","size":0,"sizes":[]},"title_color":"#E05835","title_typography_typography":"custom","title_typography_font_family":"Montserrat","title_typography_font_size":{"unit":"px","size":21,"sizes":[]},"title_typography_font_weight":"600","__globals__":{"title_color":""}},"elements":[],"widgetType":"image-box"},{"id":"8a40447","elType":"widget","settings":{"title":"שלבים בתוכניות אימון ריצה למתחילות ומתחילים","header_size":"h3","align":"right","title_color":"#040405","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"600","typography_letter_spacing":{"unit":"px","size":0.3,"sizes":[]},"typography_font_size_mobile":{"unit":"px","size":21,"sizes":[]},"_ha_condition_list":[{"_id":"8614fdb"}],"align_mobile":"center"},"elements":[],"widgetType":"heading"},{"id":"e896f06","elType":"widget","settings":{"editor":"<p><span style="color: var( --e-global-color-68f6ec0b ); font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">1. אימון ריצה והליכה לפני התחלת התוכנית של לפחות 3 ק"מ פעמיים בשבוע.</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-size: var( --e-global-typography-accent-font-size ); font-weight: var( --e-global-typography-accent-font-weight ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">2. ציוד: נעליים מתאימות לריצה וחדשות (בדיוק לא הנעליים שקנינו לפני שנתיים והם "נראות חדשות") על מנת למנוע פציעות מיותרות,&nbsp;</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">ביגוד ריצה קליל ומנדף זיעה קצר או ארוך לפי העונה הרלבנטית, ובהתאם לזה - כובע, קפוצון, מעיל רוח ועוד..&nbsp;</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">3. מסלול: נקבע מסלול ריצה מראש על מנת שנהיה בטוחים בשטח הריצה שלא יאריך את המסלול עם טעויות וגם חשיבות&nbsp;</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">לבטיחות המסלול שיהיה עביר, מואר, לא מסוכן ונעים. ככלל, נעדיף לרוץ ב<a href="http://www.parksharon.co.il/">פארקים</a>, ברחובות רחבים, בשבילים עירוניים בטוחים,</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">אך ניתן לבצע גם את תוכנית הריצה על הליכון.&nbsp;</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">4. כשתחליטו שזה בשבילכם תוכלו להתקדם מתוכניץ גנרית לתוכנית אימון ריצה למתחילים - אישית&nbsp;</span></p>
<p><span style="color: var( --e-global-color-68f6ec0b ); font-weight: var( --e-global-typography-accent-font-weight ); font-size: var( --e-global-typography-accent-font-size ); font-family: var( --e-global-typography-accent-font-family ), sans-serif;">שם&nbsp;</span><span style="font-family: Montserrat, sans-serif; font-size: 18px; color: var( --e-global-color-68f6ec0b );">תקבלו ממני הדרכה מלאה דרך אפליקציה חכמה, לאימוני ריצה, כח ותזונה, וטיפים חשובים</span></p>
<p><span style="font-family: Montserrat, sans-serif; font-size: 18px; color: var( --e-global-color-68f6ec0b );">כיצד להתכונן לאימון בשטח או בכביש, איך להתכונן נכון לתחרות ראשונה,&nbsp;</span><span style="color: var( --e-global-color-68f6ec0b ); font-family: Montserrat, sans-serif; font-size: 18px;">&nbsp;איך לרוץ במזג אויר חם או קר, כמה לישון, כמה מה לאכול ועוד המון טיפים ליישום.ש</span></p>","typography_typography":"custom","typography_font_family":"Roboto","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"500","__globals__":{"text_color":"globals/colors?id=68f6ec0b"},"typography_font_size_mobile":{"unit":"px","size":16,"sizes":[]}},"elements":[],"widgetType":"text-editor"},{"id":"4b62ee4","elType":"widget","settings":{"title":"מי אני?","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":18,"sizes":[]},"typography_font_weight":"600","__globals__":{"title_color":"globals/colors?id=68f6ec0b"},"header_size":"h4"},"elements":[],"widgetType":"heading"},{"id":"06bb07f","elType":"widget","settings":{"editor":"<p><b><a href="https://www.sport4you.co.il/about-me/">תומר אלמוג</a> <a href="https://raceview.net/#dds.php?showall=y&amp;query=%D7%AA%D7%95%D7%9E%D7%A8%20%D7%90%D7%9C%D7%9E%D7%95%D7%92">מאמן ריצה וכושר</a>&nbsp;</b>- אוביל איתכם את התהליך להצלחה! אני בעל ניסיון רב בתחום הריצה כמתאמן וכמאמן ובעל תעודות הסמכה</p>
<p>**מכון ווינגייט ליסודות האתלטיקה, **מאוניברסיטת תל אביב ,וכמאמן מנטלי מתוכנית מעוף.</p>
<p>התחריתי בתחרויות רבות בארץ ובעולם עם הישגים נאים בתחרויות 800 מטר ועד אולטרה מרתונים. מנחה ומייעץ למעל מאה מתאמנים בארץ ובעולם.</p>
<p>אני מאמן בקבוצות ריצה ברמת השרון ובתל אביב , מאמן קבוצות ילדים הישגיים ועם הפרעות קשב וריכוז. מאמן ריצה אונליין.</p>
<br>","text_color":"#030303","__globals__":{"typography_typography":""},"typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":16,"sizes":[]},"typography_font_weight":"500"},"elements":[],"widgetType":"text-editor"}],"isInner":false}],"isInner":false},{"id":"31e7d867","elType":"section","settings":{"structure":"50"},"elements":[{"id":"26c1ac52","elType":"column","settings":{"_column_size":20,"_inline_size":null},"elements":[{"id":"75484e4f","elType":"widget","settings":{"text":"תוכנית אימון ריצה מתחילים","align":"center","size":"md","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":21,"sizes":[]},"typography_font_weight":"500","typography_line_height":{"unit":"em","size":1.2,"sizes":[]},"typography_word_spacing":{"unit":"em","size":0.1,"sizes":[]},"background_color":"#12549C","border_radius":{"unit":"px","top":"29","right":"29","bottom":"29","left":"29","isLinked":true},"__dynamic__":{"link":"[elementor-tag id="d636f16" name="internal-url" settings="%7B%22type%22%3A%22post%22%2C%22post_id%22%3A%223687%22%7D"]"}},"elements":[],"widgetType":"button"}],"isInner":true},{"id":"2b358748","elType":"column","settings":{"_column_size":20,"_inline_size":null},"elements":[{"id":"554c594a","elType":"widget","settings":{"text":"תוכנית אימון ריצה 10 ק"מ","align":"center","size":"md","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":21,"sizes":[]},"typography_font_weight":"500","typography_line_height":{"unit":"em","size":1.2,"sizes":[]},"typography_word_spacing":{"unit":"em","size":0.1,"sizes":[]},"background_color":"#12549C","border_radius":{"unit":"px","top":"29","right":"29","bottom":"29","left":"29","isLinked":true},"__dynamic__":{"link":"[elementor-tag id="9fcc1a8" name="internal-url" settings="%7B%22type%22%3A%22post%22%2C%22post_id%22%3A%223685%22%7D"]"}},"elements":[],"widgetType":"button