s":{"space":{"unit":"px","size":125,"sizes":[]},"_ha_condition_list":[{"_id":"98fca54"}]},"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":true},{"id":"6d4aae74","elType":"section","settings":{"gap":"narrow","custom_height":{"unit":"px","size":65,"sizes":[]},"layout":"full_width","background_background":"classic","__globals__":{"background_color":""},"_ha_condition_list":[{"_id":"1c37c3e"}]},"elements":[{"id":"4da0c76f","elType":"column","settings":{"_column_size":100,"_ha_condition_list":[{"_id":"e37a283"}]},"elements":[{"id":"c30e6cb","elType":"widget","settings":{"html":"<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"מה זה תוכניות אימונים ריצה למתחילים?","acceptedAnswer":{"@type":"Answer","text":"תוכניות אימונים ריצה למתחילים אונליין מאפשרת לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, להגיע להישגים באופן עצמאי. התוכנית תועבר באמצעות אפליקציה מתקדמת וייעודית הכוללת תכנון שבועי / יומי עם מעקב ובקרה שוטפת שלי, תקבלו הדרכה להכנה לאימונים, תחרויות, ריצה במזגי אויר משתנים, ריצה בתנאים שטח משתנים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם"}},{"@type":"Question","name":"למי תוכניות אימונים ריצה למתחילים אונליין מתאימה?","acceptedAnswer":{"@type":"Answer","text":"תוכניות אימונים ריצה למתחילים אונליין מתאימה לרמת מתחילים - מי שלא רץ בכלל או בעברו הרחוק או מי שנמצא בנקודת התחלה עצמאית ורוצה להתקדם ולהיות תחת הדרכה הכוללת הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה וניסיון רב. המטרה להעניק לכם את היכולת להגיע למטרה שלכם -איך בכלל להתחיל לרוץ, טכניקת ריצה, הימנעות מפציעות   כנסו לאתר וקבלו איפיון המתאים עבורכם"}},{"@type":"Question","name":"האם אפשר לקבל תוכנית לדוגמא?","acceptedAnswer":{"@type":"Answer","text":"בוודאי. באתר קיימת תוכנית אימון ריצה למתחילים בחינם להורדה. חשוב לציין שהתוכנית אינה אישית והיא כוללנית. "}},{"@type":"Question","name":"תוכניות אימונים ריצה למתחילים אונליין מחיר?","acceptedAnswer":{"@type":"Answer","text":"מחיר אימוני ריצה אונליין נעים החל מ 250 ש\"ח ותלוייים במשתנים הקשורים למטרה, והאינטנסיביות של התוכנית. באתר תוכלו לקבל את המסלול המתאים עבורכם"}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"5e3b9e3","elType":"widget","settings":{"title":"שאלות נפוצות","align":"center","__globals__":{"title_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"heading"},{"id":"718ce69","elType":"widget","settings":{"tabs":[{"tab_title":"מה זה תוכניות אימונים ריצה למתחילים?","tab_content":"<p>תוכניות אימונים ריצה למתחילים אונליין מאפשרת לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, להגיע להישגים באופן עצמאי. התוכנית תועבר באמצעות אפליקציה מתקדמת וייעודית הכוללת תכנון שבועי / יומי עם מעקב ובקרה שוטפת שלי, תקבלו הדרכה להכנה לאימונים, תחרויות, ריצה במזגי אויר משתנים, ריצה בתנאים שטח משתנים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם</p>","_id":"94cdafe"},{"_id":"59134c2","tab_title":"האם אפשר לקבל תוכנית לדוגמא?","tab_content":"<p>בוודאי. באתר קיימת תוכנית אימון ריצה למתחילים בחינם להורדה. חשוב לציין שהתוכנית אינה אישית והיא כוללנית.</p>"},{"tab_title":"למי תוכניות אימונים ריצה למתחילים אונליין מתאימה?","tab_content":"<p>תוכניות אימונים ריצה למתחילים אונליין מתאימה לרמת מתחילים - מי שלא רץ בכלל או בעברו הרחוק או מי שנמצא בנקודת התחלה עצמאית ורוצה להתקדם ולהיות תחת הדרכה הכוללת הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה וניסיון רב. המטרה להעניק לכם את היכולת להגיע למטרה שלכם -איך בכלל להתחיל לרוץ, טכניקת ריצה, הימנעות מפציעות כנסו לאתר וקבלו איפיון המתאים עבורכם</p>","_id":"c01bf44"},{"_id":"7c5e88c","tab_title":"תוכניות אימונים ריצה למתחילים אונליין מחיר?","tab_content":"<p>מחיר אימוני ריצה אונליין נעים החל מ 250 ש"ח ותלוייים במשתנים הקשורים למטרה, והאינטנסיביות של התוכנית. באתר תוכלו לקבל את המסלול המתאים עבורכם</p>"}],"__globals__":{"title_color":"globals/colors?id=68f6ec0b","tab_active_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"toggle"},{"id":"6a67d047","elType":"widget","settings":{"text":"מפריד","_ha_condition_list":[{"_id":"cd71232"}