ngs":{"space":{"unit":"px","size":125,"sizes":[]},"_ha_condition_list":[{"_id":"add00d0"}]},"elements":[],"widgetType":"spacer"}],"isInner":true}],"isInner":true},{"id":"4eacb76e","elType":"section","settings":{"gap":"narrow","custom_height":{"unit":"px","size":65,"sizes":[]},"layout":"full_width","background_background":"classic","__globals__":{"background_color":"globals/colors?id=ebcc3e8"},"_ha_condition_list":[{"_id":"b6ec960"}]},"elements":[{"id":"26d547bd","elType":"column","settings":{"_column_size":100,"_ha_condition_list":[{"_id":"f4e93de"}]},"elements":[{"id":"a92f7ef","elType":"widget","settings":{"html":"<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"מה זה תוכנית אימונים חצי מרתון אונליין?","acceptedAnswer":{"@type":"Answer","text":"תוכנית אימונים אונליין לחצי מרתון מאפשרת לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, להגיע להישגים באופן עצמאי. התוכנית תועבר באמצעות אפליקציה מתקדמת וייעודית הכוללת תכנון שבועי / יומי עם מעקב ובקרה שוטפת שלי על האימונים, קצבים, תזונה, שינה, דופק. תקבלו הדרכה להכנה לאימונים, תחרויות, ריצה במזגי אויר משתנים, ריצה בתנאים שטח משתנים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם"}},{"@type":"Question","name":"למי תוכנית אימונים אונליין לחצי מרתון מתאימה?","acceptedAnswer":{"@type":"Answer","text":"תוכנית אימונים אונליין לחצי מרתון מתאימה לרמת מתחילים + שעברו כבר ריצות של 10 ק\"מ ומעלה ורוצים להתקדם ולהיות תחת הדרכה הכוללת הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה וניסיון רב. המטרה להעניק לכם את היכולת להגיע למטרה שלכם -איך בכלל לרוץ נכון, טכניקת ריצה, הימנעות מפציעות ולהגיע ליעד מכובד של ריצה רציפה בחצי מרתון  כנסו לאתר וקבלו איפיון המתאים עבורכם"}},{"@type":"Question","name":"האם אפשר לקבל תוכנית אימונים לחצי מרתון לדוגמא?","acceptedAnswer":{"@type":"Answer","text":"בוודאי. באתר קיימת תוכנית אימונים לחצי מרתון בחינם להורדה. חשוב לציין שהתוכנית אינה אישית והיא כוללנית."}},{"@type":"Question","name":"תוכנית אימונים אונליין לחצי מרתון מחיר?","acceptedAnswer":{"@type":"Answer","text":"מחיר אימוני ריצה אונליין נעים החל מ 280 ש\"ח ותלוייים במשתנים הקשורים למטרה, והאינטנסיביות של התוכנית. באתר תוכלו לקבל את המסלול המתאים עבורכם"}}]}</script>"},"elements":[],"widgetType":"html"},{"id":"bbc9de4","elType":"widget","settings":{"tabs":[{"tab_title":"מה זה תוכנית אימונים חצי מרתון אונליין?","tab_content":"<p>תוכנית אימונים אונליין לחצי מרתון מאפשרת לכל מי שרוצה לרוץ לבד ולא במסגרת קבוצתית ובלי הגדרות מיקום, להגיע להישגים באופן עצמאי. התוכנית תועבר באמצעות אפליקציה מתקדמת וייעודית הכוללת תכנון שבועי / יומי עם מעקב ובקרה שוטפת שלי על האימונים, קצבים, תזונה, שינה, דופק. תקבלו הדרכה להכנה לאימונים, תחרויות, ריצה במזגי אויר משתנים, ריצה בתנאים שטח משתנים ועוד..כנסו לאתר וגלו את אפשרויות האימון הקיימות עבורכם</p>","_id":"2f8072d"},{"tab_title":"למי תוכנית אימונים אונליין לחצי מרתון מתאימה?","tab_content":"<p>תוכנית אימונים אונליין לחצי מרתון מתאימה לרמת מתחילים + שעברו כבר ריצות של 10 ק"מ ומעלה ורוצים להתקדם ולהיות תחת הדרכה הכוללת הנחיות תזונתיות ומנטליות על ידי מאמן מנוסה וניסיון רב. המטרה להעניק לכם את היכולת להגיע למטרה שלכם -איך בכלל לרוץ נכון, טכניקת ריצה, הימנעות מפציעות ולהגיע ליעד מכובד של ריצה רציפה בחצי מרתון כנסו לאתר וקבלו איפיון המתאים עבורכם</p>","_id":"8c6a3e3"},{"_id":"be49be8","tab_title":"האם אפשר לקבל תוכנית אימונים לחצי מרתון לדוגמא?","tab_content":"<p>בוודאי. באתר קיימת תוכנית אימונים לחצי מרתון בחינם להורדה. חשוב לציין שהתוכנית אינה אישית והיא כוללנית.</p>"},{"_id":"90a034d","tab_title":"תוכנית אימונים אונליין לחצי מרתון מחיר?","tab_content":"<p>מחיר אימוני ריצה אונליין נעים החל מ 280 ש"ח ותלוייים במשתנים הקשורים למטרה, והאינטנסיביות של התוכנית. באתר תוכלו לקבל את המסלול המתאים עבורכם</p>"}],"__globals__":{"title_color":"globals/colors?id=68f6ec0b","tab_active_color":"globals/colors?id=68f6ec0b"}},"elements":[],"widgetType":"toggle"},{"id":"36d49fbb","elType":"widget","settings":{"text":"מפריד","_ha_condition_list":[{"_id":"d4fb7d5"}]},"elements":[],"widgetType":"divider"},{"id":"